/**
 * 🧠 MOTOR CENTRAL DE INTELIGÊNCIA ARTIFICIAL (FREIO ABS DE 30s)
 */
function CHAMAR_IA_ESCRITORIO(prompt, tipoModelo, tentativas = 0) {
  let modelo = (tipoModelo === "PRO") ? MODEL_PRO : MODEL_FLASH;
  let url = "https://generativelanguage.googleapis.com/v1beta/models/" + modelo + ":generateContent?key=" + API_KEY;

  let payload = {
    "contents": [{"parts": [{"text": prompt}]}]
  };

  let options = {
    "method": "post",
    "contentType": "application/json",
    "payload": JSON.stringify(payload),
    "muteHttpExceptions": true
  };

  try {
    let response = UrlFetchApp.fetch(url, options);
    let json = JSON.parse(response.getContentText());

    // Se a IA respondeu certinho de primeira
    if (json.candidates && json.candidates.length > 0) {
      return json.candidates[0].content.parts[0].text;
    } 
    // SE DER O ERRO DE COTA (429 - Too Many Requests / Quota Exceeded)
    else if (json.error && (json.error.message.includes("quota") || json.error.message.includes("exceeded"))) {
       if (tentativas < 4) {
         // 🚨 O FREIO ABS ATUANDO: O robô cruza os braços por 30 segundos e tenta de novo
         Utilities.sleep(30000); 
         return CHAMAR_IA_ESCRITORIO(prompt, tipoModelo, tentativas + 1);
       } else {
         return "❌ Cota excedida após várias tentativas. Aguarde uns 2 minutos e tente novamente.";
       }
    } 
    // Se for algum outro erro bizarro da API
    else if (json.error) {
       return "Erro da API: " + json.error.message;
    } 
    // Falha desconhecida
    else {
       return "Erro: Resposta inesperada da API.";
    }
  } catch (e) {
    return "Erro de conexão: " + e.message;
  }
}

// ==========================================
// FUNÇÕES BASE DO PILOTO AUTOMÁTICO
// ==========================================
function ligarPilotoAutomatico() {
  desligarPilotoAutomaticoSilencioso(); 

  ScriptApp.newTrigger('rodarEsteiraCompleta')
    .timeBased()
    .everyHours(1) 
    .create();

  Browser.msgBox("✅ MODO SKYNET ATIVADO", "O Piloto Automático assumiu o controle. De hora em hora o sistema vai fazer a faxina, auditar os documentos, ler as árvores dos tribunais e auto-organizar a planilha!", Browser.Buttons.OK);
}

function desligarPilotoAutomatico() {
  desligarPilotoAutomaticoSilencioso();
  Browser.msgBox("🛑 PILOTO DESLIGADO", "As varreduras automáticas foram interrompidas. O controle voltou para o modo manual.", Browser.Buttons.OK);
}

function desligarPilotoAutomaticoSilencioso() {
  let triggers = ScriptApp.getProjectTriggers();
  for (let i = 0; i < triggers.length; i++) {
    ScriptApp.deleteTrigger(triggers[i]);
  }
}

/**
 * 01 - MOTOR IA JURÍDICO V3.2 (Focado em Gemini)
 * FIX: Remoção de variáveis duplicadas (MODEL_FLASH/PRO já estão no 00_config)
 * Orquestrador de IA: Gemini Flash (Velocidade) + Gemini Pro (Raciocínio)
 * Autenticação OAuth Nativa + Gestão Inteligente de Cotas
 * Dr. Lucas Renan Semim - OAB/MG 222.539
 */

// =========================================================================
// 🤖 BLOCO 1: CONFIGURAÇÃO DE AGENTES (FAMÍLIA GEMINI)
// =========================================================================
const AGENTES = {
  GEMINI_FLASH: {
    nome: "Gemini Flash",
    modelo: MODEL_FLASH, // Puxa direto do 00_config.gs
    temperatura: 0.4,
    maxTokens: 8192,
    limite_por_minuto: 15,
    ideal_para: ["OCR", "EMAIL", "STATUS", "RESUMO", "FASE", "FLASH"]
  },
  GEMINI_PRO: {
    nome: "Gemini Pro",
    modelo: MODEL_PRO, // Puxa direto do 00_config.gs
    temperatura: 0.1,
    maxTokens: 8192,
    limite_por_minuto: 5,
    ideal_para: ["PETICAO", "DOSSIE", "TESE", "ANALISE", "ESTRATEGIA", "PRO", "JURIDICO"]
  }
};

// =========================================================================
// 🧠 BLOCO 2: MEMÓRIA DE COTAS E PROTEÇÃO (CacheService)
// =========================================================================
function registrarFalha(nomeAgente) {
  const cache = CacheService.getScriptCache();
  const key = "COTA_" + nomeAgente.replace(/\s+/g, "");
  let estado = { falhas: 0, ultimaFalha: 0, bloqueadoAte: 0 };

  try {
    const cached = cache.get(key);
    if (cached) estado = JSON.parse(cached);
  } catch (e) { console.log("[MOTOR] Erro ao ler cache: " + e.message); }

  estado.falhas += 1;
  estado.ultimaFalha = Date.now();

  if (estado.falhas >= 3) {
    estado.bloqueadoAte = Date.now() + 120000; // Bloqueia por 2 minutos (120 milissegundos)
    console.log(`[MOTOR] 🚨 Agente ${nomeAgente} BLOQUEADO temporariamente por excesso de falhas 429.`);
  }

  cache.put(key, JSON.stringify(estado), 21600); // Salva por 6 horas
}

function registrarSucesso(nomeAgente) {
  const cache = CacheService.getScriptCache();
  const key = "COTA_" + nomeAgente.replace(/\s+/g, "");
  cache.put(key, JSON.stringify({ falhas: 0, ultimaFalha: Date.now(), bloqueadoAte: 0 }), 21600);
}

function agenteDisponivel(nomeAgente) {
  const cache = CacheService.getScriptCache();
  const key = "COTA_" + nomeAgente.replace(/\s+/g, "");
  try {
    const cached = cache.get(key);
    if (cached) {
      const estado = JSON.parse(cached);
      if (estado.bloqueadoAte > Date.now()) return false;
    }
  } catch (e) { return true; } 
  return true;
}

// =========================================================================
// 🔐 BLOCO 3: AUTENTICAÇÃO INTELIGENTE NATIVA
// =========================================================================
function obterCredenciaisGemini() {
  const apiKey = PropertiesService.getScriptProperties().getProperty("GEMINI_API_KEY");
  if (apiKey && apiKey.trim() !== "") {
    return { modo: "APIKEY", valor: apiKey };
  } else {
    // Usa a autorização do próprio Google Workspace do Escritório
    return { modo: "OAUTH", valor: ScriptApp.getOAuthToken() };
  }
}

// =========================================================================
// 🎯 BLOCO 4: ROTEADOR DE TAREFAS
// =========================================================================
function rotearParaMelhorAgente(tipoTarefa) {
  if (tipoTarefa === "FLASH") return AGENTES.GEMINI_FLASH;
  if (tipoTarefa === "PRO" || tipoTarefa === "PRO_JURIDICO") return AGENTES.GEMINI_PRO;

  // Se for uma tarefa específica, busca qual agente é o ideal
  if (AGENTES.GEMINI_PRO.ideal_para.includes(tipoTarefa)) {
      return agenteDisponivel(AGENTES.GEMINI_PRO.nome) ? AGENTES.GEMINI_PRO : AGENTES.GEMINI_FLASH;
  }

  return agenteDisponivel(AGENTES.GEMINI_FLASH.nome) ? AGENTES.GEMINI_FLASH : AGENTES.GEMINI_PRO;
}

// =========================================================================
// ⚙️ BLOCO 5: EXECUTOR GEMINI (Núcleo de Processamento)
// =========================================================================
function executarGemini(agente, prompt) {
  const creds = obterCredenciaisGemini();
  let url = `https://generativelanguage.googleapis.com/v1beta/models/${agente.modelo}:generateContent`;
  let headers = { "Content-Type": "application/json" };

  if (creds.modo === "APIKEY") {
    url += `?key=${creds.valor}`;
  } else {
    headers["Authorization"] = "Bearer " + creds.valor;
  }

  const payload = {
    contents: [{ role: "user", parts: [{ text: prompt }] }],
    generationConfig: { temperature: agente.temperatura, maxOutputTokens: agente.maxTokens },
    safetySettings: [
      { category: "HARM_CATEGORY_HARASSMENT", threshold: "BLOCK_ONLY_HIGH" },
      { category: "HARM_CATEGORY_HATE_SPEECH", threshold: "BLOCK_ONLY_HIGH" },
      { category: "HARM_CATEGORY_SEXUALLY_EXPLICIT", threshold: "BLOCK_ONLY_HIGH" },
      { category: "HARM_CATEGORY_DANGEROUS_CONTENT", threshold: "BLOCK_ONLY_HIGH" }
    ]
  };

  const options = {
    method: "post",
    headers: headers,
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };

  let tentativas = 0;
  while (tentativas < 3) {
    try {
      let res = UrlFetchApp.fetch(url, options);
      let code = res.getResponseCode();
      let json = JSON.parse(res.getContentText());

      if (code === 200 && json.candidates && json.candidates.length > 0) {
        registrarSucesso(agente.nome);
        return json.candidates[0].content.parts[0].text;
      } else if (code === 429) {
        // Estourou a cota (Muitas requisições por minuto)
        tentativas++;
        registrarFalha(agente.nome);
        console.log(`[MOTOR] ⚠️ 429 ${agente.nome}. Tentativa ${tentativas}/3.`);
        Utilities.sleep(5000); // Aguarda 5 segundos antes de tentar de novo
      } else {
        // Outros erros da API (Ex: Prompt bloqueado pelo filtro de segurança)
        registrarFalha(agente.nome);
        return "❌ Erro Gemini: " + (json.error ? json.error.message : "Resposta inesperada.");
      }
    } catch (e) {
      // Erro de rede ou timeout do Google
      tentativas++;
      Utilities.sleep(3000);
    }
  }
  return "❌ Erro Crítico: " + agente.nome + " falhou após 3 tentativas seguidas (Cota ou Timeout).";
}

// =========================================================================
// 🌊 BLOCO 6: A CASCATA DE IA (A FUNÇÃO SUPREMA CHAMADA PELOS OUTROS SCRIPTS)
// =========================================================================
function CHAMAR_IA_ESCRITORIO(prompt, tipoModelo) {
  let agentePrincipal = rotearParaMelhorAgente(tipoModelo);

  // Define o reserva (Se o Flash falhar, tenta o Pro. Se o Pro falhar, tenta o Flash)
  let agenteReserva = agentePrincipal.nome === "Gemini Flash" ? AGENTES.GEMINI_PRO : AGENTES.GEMINI_FLASH;

  console.log(`[MOTOR] Tarefa: ${tipoModelo} | Acionando: ${agentePrincipal.nome}`);

  let resposta = executarGemini(agentePrincipal, prompt);

  // Se o agente principal respondeu perfeitamente, devolve a resposta
  if (!resposta.includes("❌")) return resposta;

  console.log(`[MOTOR] Falha no ${agentePrincipal.nome}. Iniciando CASCATA para o ${agenteReserva.nome}...`);

  // Se falhou, aciona o reserva, desde que ele não esteja bloqueado no Cache
  if (agenteDisponivel(agenteReserva.nome)) {
    let respostaReserva = executarGemini(agenteReserva, prompt);
    if (!respostaReserva.includes("❌")) return respostaReserva;
  }

  // Se ambos falharam, devolve o erro real para ser impresso na planilha
  return `❌ SISTEMA: Ambos os motores Gemini estão indisponíveis no momento. O último erro foi: ${resposta.replace("❌ Erro Gemini:", "").substring(0, 50)}`;
}

// =========================================================================
// 🔄 BLOCO 7: FUNÇÕES LEGADAS (COMPATIBILIDADE)
// =========================================================================
function GEMINI_FLASH(prompt) {
  return CHAMAR_IA_ESCRITORIO(prompt, "FLASH");
}

function GEMINI_PRO_AVANCADO(prompt) {
  return CHAMAR_IA_ESCRITORIO(prompt, "PRO");
}

// =========================================================================
// 🩺 BLOCO 8: DIAGNÓSTICO E CONFIGURAÇÃO (MENUS)
// =========================================================================
function testarMotoresGemini() {
  const ui = SpreadsheetApp.getUi();
  let relatorio = "STATUS DOS MOTORES GEMINI:\n\n";

  for (let key in AGENTES) {
    let agente = AGENTES[key];
    let inicio = Date.now();
    let res = executarGemini(agente, `Responda curto: ${agente.nome} ONLINE E OPERANTE.`);
    let tempo = Date.now() - inicio;

    if (res.includes("❌")) {
      relatorio += `❌ ${agente.nome}: OFFLINE (${res.substring(0, 40)}...)\n`;
    } else {
      relatorio += `✅ ${agente.nome}: ONLINE (${tempo}ms)\n`;
    }
  }

  let modoAutenticacao = obterCredenciaisGemini().modo;
  relatorio += `\n📋 Autenticação Ativa: ${modoAutenticacao === "OAUTH" ? "OAuth Nativo (Google Workspace)" : "API Key Manual"}`;

  Browser.msgBox("🔬 TESTE DE MOTORES", relatorio, Browser.Buttons.OK);
}

function verStatusCotasGemini() {
  const cache = CacheService.getScriptCache();
  let msg = "STATUS DAS COTAS (CACHE):\n\n";
  let bloqueios = 0;

  for (let key in AGENTES) {
    let agente = AGENTES[key];
    let cacheKey = "COTA_" + agente.nome.replace(/\s+/g, "");
    let cached = cache.get(cacheKey);

    if (cached) {
      let estado = JSON.parse(cached);
      if (estado.bloqueadoAte > Date.now()) {
        let minutos = Math.ceil((estado.bloqueadoAte - Date.now()) / 60000);
        msg += `⛔ ${agente.nome}: BLOQUEADO (libera em ~${minutos} min). Falhas seguidas: ${estado.falhas}\n`;
        bloqueios++;
      } else {
        msg += `🟢 ${agente.nome}: DISPONÍVEL (Falhas no histórico: ${estado.falhas})\n`;
      }
    } else {
      msg += `🟢 ${agente.nome}: DISPONÍVEL (Nenhuma falha no registro)\n`;
    }
  }

  if (bloqueios === 0) msg += "\n✅ Motor operando com 100% da capacidade.";
  Browser.msgBox("📊 STATUS DE COTAS", msg, Browser.Buttons.OK);
}

function configurarChaveGemini() {
  const props = PropertiesService.getScriptProperties();

  let keyGemini = Browser.inputBox("🔐 CONFIGURAÇÃO DE SEGURANÇA", "Digite sua GEMINI_API_KEY\n(Ou deixe EM BRANCO e dê OK para usar o OAuth nativo gratuito do Google):", Browser.Buttons.OK_CANCEL);

  if (keyGemini !== "cancel") {
    if (keyGemini.trim() === "") {
        props.deleteProperty("GEMINI_API_KEY");
        Browser.msgBox("✅ SUCESSO", "Chave removida. O sistema agora usará o OAuth Nativo.", Browser.Buttons.OK);
    } else {
        props.setProperty("GEMINI_API_KEY", keyGemini.trim());
        Browser.msgBox("✅ SUCESSO", "Nova chave de API registrada no cofre.", Browser.Buttons.OK);
    }
  }
}

/**
 * 02 - MAPEADOR DE ELITE V16.0 (AUDITOR JURÍDICO PROFUNDO)
 * V16: Leitura Profunda de Conteúdo (Procuração/Contrato/Hipo)
 * Auditoria em Cascata OCR + Busca no Dossiê Vivo e Árvore
 * Memória de Posição + Totalizador JS Puro
 * Dr. Lucas Renan Semim - OAB/MG 222.539
 */

const PASTAS_IGNORADAS = ["ANJOS", "MODELO", "BANCO", "LIXO", "ARQUIVADOS", "00_"];
const SUBPASTAS_PADRAO = ["01_Docs_Pessoais", "02_Provas", "03_Andamentos_Despachos"];
const MAX_PASTAS_POR_CICLO = 10; // Reduzido levemente pois a leitura profunda gasta mais tempo
const MARCADOR_KEY = "MAPEADOR_ULTIMA_PASTA_ID";

function mapeamentoTotalEscritorio(modoSilencioso = false) {
  const tempoInicio = Date.now();
  const limiteTempo = 270000; // 4.5 min

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getActiveSheet();
  const nomeAba = sheet.getName();

  if (nomeAba === "📧 MÁQUINA DE EMAILS") return;
  if (nomeAba !== "Dashboard Principal" && nomeAba !== "PROCESSOS" && nomeAba !== "📱 ESTEIRA FACEBOOK") {
      if (!modoSilencioso) Browser.msgBox("❌ ERRO", "Execute nas abas corretas (Dashboard ou Esteira).", Browser.Buttons.OK);
      return;
  }

  const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO);
  let pastaAlvo;
  try {
    if (nomeAba === "📱 ESTEIRA FACEBOOK") {
      pastaAlvo = pastaRaiz.getFoldersByName("04_ESTEIRA_FACEBOOK").next().getFoldersByName("01_CLIENTES_EXECUCAO").next();
    } else {
      pastaAlvo = pastaRaiz.getFoldersByName("01_CLIENTES").next();
    }
  } catch (e) {
    console.log("[MAPEADOR] Erro: Pasta alvo não encontrada na estrutura.");
    return;
  }

  const pastasDrive = pastaAlvo.getFolders();
  let dadosPlanilha = sheet.getDataRange().getValues();

  const props = PropertiesService.getScriptProperties();
  let marcadorId = props.getProperty(MARCADOR_KEY);
  let achouMarcador = !marcadorId; 

  let stats = { processadas: 0, novas: 0, cnjExtraido: 0, emailExtraido: 0, docsProfundosLidos: 0 };
  let ultimoIdProcessado = null;

  while(pastasDrive.hasNext()) {
    if (Date.now() - tempoInicio > limiteTempo) {
        console.log("[MAPEADOR] Limite de tempo atingido. Salvando posição.");
        break;
    }
    if (stats.processadas >= MAX_PASTAS_POR_CICLO) break;

    let pastaCli = pastasDrive.next();
    let idPasta = pastaCli.getId(); 

    if (!achouMarcador) {
        if (idPasta === marcadorId) achouMarcador = true;
        continue;
    }

    let nomePasta = pastaCli.getName();
    let linkPasta = pastaCli.getUrl();

    if (PASTAS_IGNORADAS.some(termo => nomePasta.toUpperCase().includes(termo)) || nomePasta.startsWith("00_")) continue;

    let linhaAlvo = -1;
    let colLink = (nomeAba === "📱 ESTEIRA FACEBOOK") ? 4 : 5; 
    let statusIAAtual = "";

    for (let i = 2; i < dadosPlanilha.length; i++) {
      let valorId = String(dadosPlanilha[i][colLink-1]); 
      let valorNome = String(dadosPlanilha[i][1]); 
      if (valorId.includes(idPasta) || valorNome === "CLIENTE: " + nomePasta.replace("CLIENTE: ", "")) {
        linhaAlvo = i + 1; 
        statusIAAtual = String(dadosPlanilha[i][3]); // Coluna D (Status IA) ou o local onde você guarda a validação antiga
        break;
      }
    }

    if (linhaAlvo === -1) {
      linhaAlvo = Math.max(sheet.getLastRow() + 1, 3);
      sheet.getRange(linhaAlvo, colLink).setValue(linkPasta);
      stats.novas++;
      dadosPlanilha = sheet.getDataRange().getValues();
    }

    if (nomeAba === "📱 ESTEIRA FACEBOOK") {
      sheet.getRange(linhaAlvo, 1, 1, 2).setValues([[new Date(), nomePasta]]);
      stats.processadas++;
      ultimoIdProcessado = idPasta;
      continue;
    }

    // 🔎 AUDITORIA PROFUNDA (DASHBOARD)
    try {
        // Se a planilha já diz que está "✅ COMPLETO", podemos pular a leitura profunda para economizar tempo
        let jaVerificadoAnteriormente = statusIAAtual.includes("✅ COMPLETO") || statusIAAtual.includes("✅ Dossiê OK");

        let auditoria = auditarPastaClienteProfundo(pastaCli, nomePasta, jaVerificadoAnteriormente);
        let cnjExtraido = extrairCNJdoNome(nomePasta);
        let tribunalDetectado = detectarTribunalPeloCNJ(cnjExtraido);

        let prazoAtual = "";
        if (linhaAlvo <= dadosPlanilha.length) {
            prazoAtual = String(dadosPlanilha[linhaAlvo-1][7]); 
        }

        let statusFinal = construirStatusDocumentacao(auditoria, prazoAtual, nomePasta);

        if (cnjExtraido !== "") stats.cnjExtraido++;
        if (auditoria.emailEncontrado !== "") stats.emailExtraido++;
        stats.docsProfundosLidos += auditoria.docsLidosProfundamente;

        let dataHoraAtual = new Date();
        let horaFormatada = Utilities.formatDate(dataHoraAtual, "GMT-3", "HH:mm:ss");
        let nomeCliLimpo = "CLIENTE: " + nomePasta.replace("CLIENTE: ", "");

        let emailPlanilha = linhaAlvo <= dadosPlanilha.length ? String(dadosPlanilha[linhaAlvo-1][2]).trim() : "";
        let emailParaSalvar = (emailPlanilha === "" && auditoria.emailEncontrado !== "") ? auditoria.emailEncontrado : emailPlanilha;

        sheet.getRange(linhaAlvo, 1, 1, 5).setValues([[dataHoraAtual, nomeCliLimpo, emailParaSalvar, statusFinal, linkPasta]]);
        sheet.getRange(linhaAlvo, 10, 1, 2).setValues([[dataHoraAtual, horaFormatada]]);

        let cnjPlanilha = linhaAlvo <= dadosPlanilha.length ? String(dadosPlanilha[linhaAlvo-1][8]).trim() : "";
        if (cnjPlanilha === "" && cnjExtraido !== "") sheet.getRange(linhaAlvo, 9).setValue(cnjExtraido);

        let tribPlanilha = linhaAlvo <= dadosPlanilha.length ? String(dadosPlanilha[linhaAlvo-1][14]).trim() : "";
        if (tribPlanilha === "" && tribunalDetectado !== "") sheet.getRange(linhaAlvo, 15).setValue(tribunalDetectado);

    } catch(e) {
        console.log(`[MAPEADOR] Erro ao auditar ${nomePasta}: ${e.message}`);
    }

    stats.processadas++;
    ultimoIdProcessado = idPasta;
  }

  if (!pastasDrive.hasNext()) {
      props.deleteProperty(MARCADOR_KEY);
      console.log("[MAPEADOR] Ciclo completo.");
  } else if (ultimoIdProcessado) {
      props.setProperty(MARCADOR_KEY, ultimoIdProcessado);
  }

  if (nomeAba !== "📱 ESTEIRA FACEBOOK") {
      atualizarTotalizadorMapeador(sheet);
  }

  if (!modoSilencioso) {
      try { aplicarDesignProfissional(true); } catch(e) {}
      Browser.msgBox("🚜 MAPEADOR V16.0 (AUDITOR PROFUNDO)", 
          `Auditoria Finalizada com Sucesso!\n\n` +
          `📁 Pastas Processadas: ${stats.processadas}\n` +
          `📖 Docs Lidos Profundamente: ${stats.docsProfundosLidos}\n` +
          `🆕 Clientes Adicionados: ${stats.novas}\n` +
          `📧 Emails Capturados Auto: ${stats.emailExtraido}\n` +
          `🔎 CNJs Extraídos: ${stats.cnjExtraido}`, 
          Browser.Buttons.OK);
  }
}

