/**
 * 04 - SABUJO DE ANDAMENTOS (INTEGRAÇÃO GMAIL + GEMINI)
 * Lê intimações no e-mail, extrai prazos com a IA e joga na planilha.
 */

function lerIntimacoesGmail() {
  // Abre ou cria a aba "Controle de Prazos"
  const spreadsheet = SpreadsheetApp.getActiveSpreadsheet();
  let sheetPrazos = spreadsheet.getSheetByName("Controle de Prazos");

  if (!sheetPrazos) {
    sheetPrazos = spreadsheet.insertSheet("Controle de Prazos");
    sheetPrazos.appendRow(["Data Leitura", "Processo", "Ação Necessária", "Prazo Identificado pela IA", "Link do E-mail"]);
    sheetPrazos.getRange("A1:E1").setFontWeight("bold");
  }

  // Busca e-mails não lidos dos últimos dias que contenham palavras-chave
  // Adapte a busca se você usar um serviço específico (ex: "from:recorte@advise.com.br is:unread")
  const busca = "subject:(intimação OR publicação) is:unread";
  const threads = GmailApp.search(busca, 0, 10); // Pega as 10 primeiras para não sobrecarregar

  if (threads.length === 0) {
    Browser.msgBox("🔍 STATUS", "Nenhuma nova intimação não lida encontrada no seu Gmail.", Browser.Buttons.OK);
    return;
  }

  // Notifica o início do trabalho
  spreadsheet.toast("Lendo " + threads.length + " intimações no Gmail...", "Sabujo Ativado", 5);

  for (let i = 0; i < threads.length; i++) {
    const mensagens = threads[i].getMessages();
    const ultimaMensagem = mensagens[mensagens.length - 1]; // Pega a mensagem mais recente da thread

    const assunto = ultimaMensagem.getSubject();
    const corpoTexto = ultimaMensagem.getPlainBody().substring(0, 3000); // Limita o tamanho para a IA ler mais rápido
    const linkEmail = threads[i].getPermalink();

    // O Cérebro entra em ação: Interpretação Jurídica do E-mail
    const prompt = `Você é um advogado focado em controle de prazos processuais.
    Analise o texto deste e-mail de intimação:
    "${corpoTexto}"

    Extraia as seguintes informações precisas e seja extremamente conciso:
    1. Qual o número do processo (se houver)?
    2. O que o advogado deve fazer (Ex: Pagar custas, Apresentar Contestação, Comparecer em Audiência)?
    3. Existe algum prazo mencionado (em dias ou data específica)?

    Responda EXATAMENTE neste formato (usando o separador | ):
    [Número do Processo] | [Resumo da Ação] | [Prazo ou 'Sem prazo claro']`;

    const analiseIA = GEMINI_FLASH(prompt);

    // Tratamento de segurança caso a API falhe
    if (analiseIA.includes("Erro da API")) {
      Logger.log("Falha ao analisar o email: " + assunto);
      continue; 
    }

    // Divide a resposta da IA pelas barras verticais para organizar nas colunas
    const dadosExtraidos = analiseIA.split("|");

    let processo = dadosExtraidos[0] ? dadosExtraidos[0].trim() : "Não identificado";
    let acao = dadosExtraidos[1] ? dadosExtraidos[1].trim() : "Análise Manual Necessária";
    let prazo = dadosExtraidos[2] ? dadosExtraidos[2].trim() : "Verificar";

    // Salva os dados estruturados na planilha
    sheetPrazos.appendRow([
      Utilities.formatDate(new Date(), "GMT-3", "dd/MM/yyyy HH:mm"),
      processo,
      acao,
      prazo,
      linkEmail
    ]);

    // Marca o e-mail como lido para não processá-lo novamente na próxima vez
    threads[i].markRead();

    // Pausa de segurança para respeitar o limite de requisições do motor Gemini Flash
    Utilities.sleep(2000); 
  }

  Browser.msgBox("✅ VIGILÂNCIA CONCLUÍDA", "Novas intimações foram lidas e os prazos foram extraídos para a aba 'Controle de Prazos'.", Browser.Buttons.OK);
}

