function substituirDadosDoc(docId, nome, nacionalidade, estadoCivil, profissao, cpf, endereco) {
  const doc = DocumentApp.openById(docId);
  const body = doc.getBody();

  // O 'String()' garante que números (como CPF) sejam lidos como texto sem travar o Docs
  body.replaceText("{{NOME}}", String(nome) || "Não informado");
  body.replaceText("{{NACIONALIDADE}}", String(nacionalidade) || "Brasileiro(a)");
  body.replaceText("{{ESTADO_CIVIL}}", String(estadoCivil) || "Estado Civil");
  body.replaceText("{{PROFISSAO}}", String(profissao) || "Profissão");
  body.replaceText("{{CPF}}", String(cpf) || "CPF");
  body.replaceText("{{ENDERECO}}", String(endereco) || "Endereço Completo");

  doc.saveAndClose();
}

