// 🌙 2. FUNÇÃO EM LOTE (Chamada pelo Maestro)
// =========================================================================
function analisarDespachosEmLote(modoSilencioso = false, linhaInicio = 3) {
  const tempoInicio = Date.now();
  const limiteTempo = 270000; // 4.5 minutos

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName("Dashboard Principal") || ss.getSheetByName("PROCESSOS");
  if (!sheet) return linhaInicio;

  const dados = sheet.getDataRange().getValues();
  const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO);
  const pastasClientes = pastaRaiz.getFoldersByName("01_CLIENTES");
  if (!pastasClientes.hasNext()) return linhaInicio;

  let filaDeProcessamento = [];

  // PASSO 1: Classificar urgência de todos a partir da linha de início
  // 🗺️ REGRA GEOGRÁFICA: Índice 2 = Linha 3
  let idxInicio = Math.max(linhaInicio - 1, 2);

  for (let i = idxInicio; i < dados.length; i++) {
    let clienteStr = String(dados[i][1]); // Coluna B
    let urlPasta = String(dados[i][4]);   // Coluna E

    if (clienteStr.includes("CLIENTE:") && urlPasta.includes("drive.google.com")) {
       let idPasta = urlPasta.split("folders/")[1]?.split("?")[0];
       if (!idPasta) continue;

       try {
           let pastaCliente = DriveApp.getFolderById(idPasta);
           let status = verificarSeClientePrecisaAnalise(dados[i], pastaCliente);

           if (status.precisa) {
               filaDeProcessamento.push({
                   linha: i + 1,
                   clienteStr: clienteStr,
                   urgencia: status.urgencia,
                   motivo: status.motivo
               });
           }
       } catch (e) { console.log("[JURISTA] Erro ao classificar linha " + (i+1) + ": " + e.message); }
    }
  }

  // PASSO 2: Ordenar por Urgência (CRITICA > ALTA > NORMAL > BAIXA)
  const peso = { "CRITICA": 4, "ALTA": 3, "NORMAL": 2, "BAIXA": 1 };
  filaDeProcessamento.sort((a, b) => peso[b.urgencia] - peso[a.urgencia]);

  let processados = { CRITICA: 0, ALTA: 0, NORMAL: 0, BAIXA: 0, TOTAL: 0 };
  let ultimaLinhaLida = linhaInicio;

  // PASSO 3: Processar Lote (Máximo 5 - REGRA DE COTA)
  for (let item of filaDeProcessamento) {
      if (Date.now() - tempoInicio > limiteTempo) {
          console.log("[JURISTA] Limite de tempo do lote atingido.");
          break;
      }
      if (processados.TOTAL >= MAX_IA_CALLS_JURISTA) break; 

      // Limites por categoria no lote
      if (item.urgencia === "CRITICA" && processados.CRITICA >= 3) continue;
      if (item.urgencia === "ALTA" && processados.ALTA >= 2) continue;
      if ((item.urgencia === "NORMAL" || item.urgencia === "BAIXA") && processados.TOTAL >= 4) continue;

      console.log(`[JURISTA] Analisando: ${item.clienteStr} | Urgência: ${item.urgencia} (${item.motivo})`);
      sheet.getRange("A1").setValue(`🧠 Jurista: Processando linha ${item.linha}... (${item.urgencia})`).setFontColor("#9B59B6");
      SpreadsheetApp.flush();

      processarAnaliseUnica(sheet, item.linha, item.clienteStr, true);

      processados[item.urgencia]++;
      processados.TOTAL++;
      ultimaLinhaLida = item.linha;
  }

  console.log(`[JURISTA] Lote finalizado. Total: ${processados.TOTAL} (Crit: ${processados.CRITICA}, Alta: ${processados.ALTA}, Norm: ${processados.NORMAL}, Baixa: ${processados.BAIXA})`);
  return ultimaLinhaLida + 1; // Retorna próxima linha
}

