function varreduraContinua() {
  deletarTriggersAntigos('varreduraContinua');

  const props = PropertiesService.getScriptProperties();
  let ultimaLinha = parseInt(props.getProperty("DOSSIE_ULTIMA_LINHA")) || 3;

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName("Dashboard Principal") || ss.getSheetByName("PROCESSOS");
  const totalLinhas = sheet.getLastRow();

  console.log(`[JURISTA] Fôlego Infinito ativado. Retomando da linha ${ultimaLinha}`);

  let proximaLinha = analisarDespachosEmLote(true, ultimaLinha);

  if (proximaLinha > totalLinhas) {
      console.log("[JURISTA] Ciclo completo. Resetando para linha 3.");
      props.setProperty("DOSSIE_ULTIMA_LINHA", "3");
      sheet.getRange("A1").setValue("DATA ANÁLISE").setFontColor("#FFFFFF");
  } else {
      props.setProperty("DOSSIE_ULTIMA_LINHA", proximaLinha.toString());
      sheet.getRange("A1").setValue(`🔄 Jurista: Retomando em 2 min (linha ${proximaLinha}/${totalLinhas})`).setFontColor("#E67E22");

      ScriptApp.newTrigger('varreduraContinua')
        .timeBased()
        .after(2 * 60 * 1000) // Agenda para daqui a 2 minutos
        .create();
  }
}

