// 🛠️ FUNÇÕES AUXILIARES
// =========================================================================

function verificarSeClientePrecisaAnalise(dadosLinha, pastaCliente) {
  let statusIA = String(dadosLinha[5]); // Col F
  let prazo = String(dadosLinha[7]); // Col H
  let dataVarredura = dadosLinha[9] instanceof Date ? dadosLinha[9] : new Date(0); // Col J
  let dataArvore = dadosLinha[16] instanceof Date ? dadosLinha[16] : new Date(0); // Col Q
  let fase = String(dadosLinha[17]); // Col R

  let result = { precisa: false, motivo: "", urgencia: "NENHUMA", novoArquivoDetectado: false };

  let ultimaModDrive = new Date(0);
  try {
      let files = pastaCliente.getFiles();
      let c = 0;
      while(files.hasNext() && c < 30) {
          let f = files.next();
          if (f.getLastUpdated() > ultimaModDrive) ultimaModDrive = f.getLastUpdated();
          c++;
      }
  } catch(e) {}

  if (ultimaModDrive > dataVarredura) result.novoArquivoDetectado = true;

  if (statusIA.includes("❌")) return { precisa: true, motivo: "Corrigir erro", urgencia: "CRITICA" };
  if (prazo.match(/\d{2}\/\d{2}\/\d{4}/)) {
      let p = prazo.match(/(\d{2})\/(\d{2})\/(\d{4})/);
      let d = new Date(p[3], parseInt(p[2])-1, p[1]);
      let hj = new Date(); hj.setHours(0,0,0,0);
      if ((d - hj) / (1000*60*60*24) <= 3) return { precisa: true, motivo: "Prazo Crítico", urgencia: "CRITICA" };
  }

  if (statusIA === "" || statusIA.includes("⏳")) return { precisa: true, motivo: "Análise Inicial", urgencia: "ALTA" };
  if (result.novoArquivoDetectado) return { precisa: true, motivo: "Novo documento", urgencia: "ALTA", novoArquivoDetectado: true };

  if (dataArvore > dataVarredura) return { precisa: true, motivo: "Novos andamentos", urgencia: "NORMAL" };
  if (!statusIA.includes("✅") && !statusIA.includes("🚨") && !statusIA.includes("⚠️")) return { precisa: true, motivo: "Pendente", urgencia: "NORMAL" };

  let diasDesdeUltimaAnalise = (new Date() - dataVarredura) / (1000*60*60*24);
  if (diasDesdeUltimaAnalise > 7 && !fase.includes("100%")) return { precisa: true, motivo: "Atualização Periódica", urgencia: "BAIXA" };

  return result;
}

function coletarContextoCompleto(pastaCliente, nomeCliente) {
  let dados = { textoTotal: "", tipoAreaDireito: "CIVIL_GERAL", documentosLidos: [], temPDF: false };

  let arquivosCandidatos = [];
  function mapearPasta(pasta) {
      let arqs = pasta.getFiles();
      while(arqs.hasNext()) arquivosCandidatos.push(arqs.next());
  }

  mapearPasta(pastaCliente);
  let subpastas = pastaCliente.getFolders();
  while(subpastas.hasNext()) mapearPasta(subpastas.next());

  arquivosCandidatos.sort((a, b) => b.getLastUpdated() - a.getLastUpdated());

  let sentencas = [], arvores = [], dossies = [], peticoes = [], outros = [];

  for (let arq of arquivosCandidatos) {
      let nome = arq.getName().toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
      if (nome.match(/(sentenca|decisao|acordao|despacho)/)) sentencas.push(arq);
      else if (nome.match(/(arvore|movimentacao)/)) arvores.push(arq);
      else if (nome.match(/(dossie vivo)/)) dossies.push(arq);
      else if (nome.match(/(peticao|contestacao|recurso|apelacao)/)) peticoes.push(arq);
      else outros.push(arq);
  }

  function lerArquivo(arq, limiteChars) {
      let docTempId = null;
      try {
          let texto = "";
          if (arq.getMimeType() === MimeType.GOOGLE_DOCS) {
              texto = DocumentApp.openById(arq.getId()).getBody().getText();
          } else if (arq.getMimeType() === MimeType.PDF && arq.getSize() < 5000000) { 
              dados.temPDF = true;
              let temp = Drive.Files.copy({title: "Temp_OCR", mimeType: MimeType.GOOGLE_DOCS}, arq.getId(), {ocr: true, ocrLanguage: 'pt-BR'});
              docTempId = temp.id;
              texto = DocumentApp.openById(docTempId).getBody().getText();
          }

          if (texto.length > 0) {
             let recorte = texto.length > limiteChars ? texto.substring(texto.length - limiteChars) : texto; 
             dados.textoTotal += `\n\n[DOC: ${arq.getName()}]\n${recorte}`;
             dados.documentosLidos.push(arq.getName());
          }
      } catch(e) { console.log(`[JURISTA] Erro lendo ${arq.getName()}: ${e.message}`); }
      finally {
          if (docTempId) Drive.Files.remove(docTempId); // 🛡️ REGRA LIXEIRO
      }
  }

  for (let s of sentencas) lerArquivo(s, 8000);
  for (let a of arvores) lerArquivo(a, 6000);
  if (dossies.length > 0) lerArquivo(dossies[0], 3000);
  for (let p of peticoes) lerArquivo(p, 5000);
  if (dados.textoTotal.length < 15000) {
      for (let o of outros) lerArquivo(o, 2000);
  }

  dados.textoTotal = dados.textoTotal.substring(0, 25000); 
  dados.tipoAreaDireito = detectarAreaDireito(dados.textoTotal.substring(0, 2000));

  return dados;
}

function detectarAreaDireito(texto) {
  let txt = texto.toLowerCase();
  if (txt.match(/(flagrante|inquérito|denúncia|réu|habeas corpus|prisão|pena|dosimetria|lep|regime)/)) {
      if (txt.match(/(remição|progressão|livramento|saída temporária|pad|falta grave)/)) return "EXECUCAO_PENAL";
      return "CRIMINAL";
  }
  if (txt.match(/(reclamante|reclamado|ctps|fgTS|rescisão|aviso prévio|trt|clt|horas extras)/)) return "TRABALHISTA";
  if (txt.match(/(inss|auxílio-doença|aposentadoria|perícia médica|cid|incapacidade)/)) return "PREVIDENCIARIO";
  if (txt.match(/(divórcio|guarda|alimentos|regime de bens|união estável|partilha|visitação)/)) return "FAMILIA";
  if (txt.match(/(cdc|fornecedor|produto defeituoso|negativação|financiamento)/)) return "CONSUMIDOR";
  if (txt.match(/(título executivo|penhora|sisbajud|leilão|embargos à execução)/)) return "EXECUCAO";

  return "CIVIL_GERAL";
}

