function extrairTodasAsTags(texto) {
  const tags = ["CLASSE_PROCESSUAL", "PARTE_CONTRARIA", "FASE_DO_PROCESSO", "RESUMO_FATOS_E_ANDAMENTO", 
                "PROXIMA_ACAO_ESTRATEGICA", "PRAZO_DETECTADO", "VALOR_DA_CAUSA", "NIVEL_URGENCIA", 
                "TIPO_MINUTA", "MINUTA_ADEQUADA", "ALERTA_ESTRATEGICO"];
  let result = {};

  tags.forEach(tag => {
      let m = texto.match(new RegExp("\\[" + tag + "\\]([\\s\\S]*?)(?:\\[\\/" + tag + "\\])", "i"));
      result[tag.toLowerCase()] = m && m[1] ? m[1].replace(/^\*\*|\*\*$/g, "").trim() : "Não extraído.";
  });

  result.resumo = result.resumo_fatos_e_andamento;
  result.proximaAcao = result.proxima_acao_estrategica;

  return result;
}

function atualizarDocumentoDossie(pastaCliente, dadosAnalise, nomeCliente, isLote) {
  let nomeDossie = "DOSSIÊ VIVO - " + nomeCliente;
  let busca = pastaCliente.searchFiles(`title = '${nomeDossie}'`);
  let doc;

  if (busca.hasNext()) {
      doc = DocumentApp.openById(busca.next().getId());
  } else {
      doc = DocumentApp.create(nomeDossie);
      let gavetas = pastaCliente.getFoldersByName("03_Andamentos_Despachos");
      DriveApp.getFileById(doc.getId()).moveTo(gavetas.hasNext() ? gavetas.next() : pastaCliente);
  }

  let body = doc.getBody();
  let textoAntigo = body.getText();

  let historicoArray = [];
  if (textoAntigo.includes("📅 HISTÓRICO DE ATUALIZAÇÕES")) {
      let parteHistorico = textoAntigo.split("📅 HISTÓRICO DE ATUALIZAÇÕES")[1];
      let linhas = parteHistorico.split("\n");
      for (let l of linhas) {
          if (l.trim().startsWith("📅")) historicoArray.push(l.trim());
      }
  }

  let dataStr = Utilities.formatDate(new Date(), "GMT-3", "dd/MM/yyyy HH:mm");
  let tipoRun = isLote ? "ROBÔ" : "MANUAL";
  historicoArray.unshift(`📅 ${dataStr} (${tipoRun}) — Fase: ${dadosAnalise.fase_do_processo}`);
  historicoArray = historicoArray.slice(0, 10); 

  let alertaVisual = "✅ Sem alertas críticos no momento.";
  if (dadosAnalise.nivel_urgencia === "CRITICA") alertaVisual = "🚨 PRAZO FATAL DETECTADO: " + dadosAnalise.prazo_detectado;
  else if (dadosAnalise.nivel_urgencia === "ALTA") alertaVisual = "⚠️ ATENÇÃO: " + dadosAnalise.alerta_estrategico;

  body.clear();

  body.appendParagraph("═══════════════════════════════════════════").setBold(true);
  body.appendParagraph("📂 DOSSIÊ VIVO — " + nomeCliente.toUpperCase()).setBold(true).setFontSize(14).setAlignment(DocumentApp.HorizontalAlignment.CENTER);
  body.appendParagraph("═══════════════════════════════════════════").setBold(true).setAlignment(DocumentApp.HorizontalAlignment.LEFT);

  let pAlerta = body.appendParagraph("⚠️ ALERTAS ATIVOS\n" + alertaVisual);
  if (dadosAnalise.nivel_urgencia === "CRITICA") pAlerta.setForegroundColor("#C5221F").setBold(true);

  body.appendParagraph("═══════════════════════════════════════════").setBold(true).setForegroundColor("#000000");
  body.appendParagraph("📊 STATUS ATUAL DO PROCESSO").setBold(true);
  body.appendParagraph("Fase: " + dadosAnalise.fase_do_processo);
  body.appendParagraph(dadosAnalise.resumo);

  body.appendParagraph("═══════════════════════════════════════════").setBold(true);
  body.appendParagraph("🎯 ESTRATÉGIA E PRÓXIMA AÇÃO").setBold(true);
  body.appendParagraph(dadosAnalise.proximaAcao);

  body.appendParagraph("═══════════════════════════════════════════").setBold(true);
  body.appendParagraph("📄 MINUTA SUGERIDA (" + dadosAnalise.tipo_minuta + ")").setBold(true);
  body.appendParagraph(dadosAnalise.minuta_adequada);

  body.appendParagraph("═══════════════════════════════════════════").setBold(true);
  body.appendParagraph("📅 HISTÓRICO DE ATUALIZAÇÕES").setBold(true);
  for (let h of historicoArray) body.appendParagraph(h);

  doc.saveAndClose();
}

