function formatarDashboardPrincipal(sheet) {
  const maxCols = Math.max(sheet.getMaxColumns(), 20);
  if (sheet.getMaxColumns() < 20) sheet.insertColumnsAfter(sheet.getMaxColumns(), 20 - sheet.getMaxColumns());

  const ultimaLinha = Math.max(sheet.getLastRow(), 3);

  // 🧠 CÁLCULO DOS TOTALIZADORES VIA JAVASCRIPT (SEM FÓRMULAS NO SHEETS)
  let processosAtivos = 0, prazosCriticos = 0, dossiesOk = 0, semDossie = 0, docCritico = 0;

  if (ultimaLinha >= 3) {
      const dados = sheet.getRange(3, 1, ultimaLinha - 2, 20).getValues();
      let hj = new Date(); hj.setHours(0,0,0,0);

      for (let r of dados) {
          if (String(r[1]).includes("CLIENTE:")) processosAtivos++;

          let prazo = r[7];
          if (prazo instanceof Date) {
              let p = new Date(prazo); p.setHours(0,0,0,0);
              if ((p - hj) / 86400000 <= 3) prazosCriticos++;
          } else if (String(prazo).match(/\d{2}\/\d{2}\/\d{4}/)) {
              let pts = String(prazo).match(/(\d{2})\/(\d{2})\/(\d{4})/);
              let p = new Date(pts[3], parseInt(pts[2])-1, pts[1]);
              if ((p - hj) / 86400000 <= 3) prazosCriticos++;
          }

          let statusD = String(r[3]);
          if (statusD.includes("SEM DOSSIÊ")) semDossie++;
          if (statusD.includes("CRÍTICO")) docCritico++;

          let statusF = String(r[5]);
          if (statusF.includes("✅")) dossiesOk++;
      }
  }

  // Limpeza Estrutural das Linhas 1 e 2
  sheet.getRange(1, 1, 2, maxCols).breakApart();
  sheet.getRange(1, 1, 2, maxCols).clearContent();

  // INJEÇÃO ESTÁTICA BLINDADA DA LINHA 1
  sheet.setRowHeight(1, 38);
  let dataFormatada = Utilities.formatDate(new Date(), "GMT-3", "dd/MM/yyyy HH:mm");

  const configLinha1 = [
    { r: "A1:B1", txt: "⚖️ SEMIM & ASSOCIADOS", bg: "#0C1B33", fc: "#D4AF37" },
    { r: "C1:D1", txt: `${processosAtivos} PROCESSOS ATIVOS`, bg: "#1a2f4e", fc: "#FFFFFF" },
    { r: "E1:F1", txt: `🚨 ${prazosCriticos} PRAZOS CRÍTICOS`, bg: "#B31412", fc: "#FFFFFF" },
    { r: "G1:H1", txt: `📋 ${dossiesOk} DOSSIÊS OK`, bg: "#137333", fc: "#FFFFFF" },
    { r: "I1:J1", txt: `⚠️ ${semDossie} SEM DOSSIÊ`, bg: "#E37400", fc: "#FFFFFF" },
    { r: "K1:L1", txt: `🔴 ${docCritico} DOC CRÍTICO`, bg: "#C0392B", fc: "#FFFFFF" },
    { r: "M1:T1", txt: `Última atualização: ${dataFormatada}`, bg: "#2c3e50", fc: "#D4AF37", it: true }
  ];

  for (let c of configLinha1) {
    let rng = sheet.getRange(c.r);
    rng.merge().setValue(c.txt).setBackground(c.bg).setFontColor(c.fc).setFontWeight("bold").setHorizontalAlignment("center").setVerticalAlignment("middle").setFontSize(10);
    if (c.it) rng.setFontStyle("italic");
  }

  // INJEÇÃO DOS CABEÇALHOS NA LINHA 2
  sheet.setRowHeight(2, 52);
  const cabecalhos = [
    "DATA ANÁLISE", "CLIENTE / PASTA", "E-MAIL DO CLIENTE", 
    "STATUS DOCUMENTAÇÃO", "LINK DA PASTA", "STATUS IA / DOSSIÊ", 
    "CLASSE PROCESSUAL", "⏰ PRAZO FATAL", "PROCESSO (CNJ)", 
    "ÚLTIMA VARREDURA", "HORA DA VARREDURA", "PARTE CONTRÁRIA", "RESUMO DO PROCESSO", "PRÓXIMA AÇÃO (ESTRATÉGIA)", 
    "SISTEMA (TRIBUNAL)", "EXPEDIENTES PENDENTES", "LEITURA ÁRVORE", 
    "FASE DO PROCESSO", "VALOR DA CAUSA", "APLICAÇÃO DE TESE"
