function criarOuObterAba(ss, nomeAba) {
  let aba = ss.getSheetByName(nomeAba);
  if (!aba) aba = ss.insertSheet(nomeAba);
  return aba;
}

function gerarBarraVisual(percentual) {
  let p = parseInt(percentual) || 0;
  if (p < 0) p = 0; if (p > 100) p = 100;

  let blocos = Math.round(p / 10);
  let barra = "[" + "█".repeat(blocos) + "░".repeat(10 - blocos) + "] " + p + "%";

  if (p === 100) return "⭐ " + barra;
  if (p >= 76) return "🟢 " + barra;
  if (p >= 51) return "🔵 " + barra;
  if (p >= 26) return "🟠 " + barra;
  return "🔴 " + barra;
}

