  // Memória de Posição e Aprendizado
  let marcadorPastaId = props.getProperty("OCR_ULTIMA_PASTA_ID");
  let arquivosProcessados = [];
  try { arquivosProcessados = JSON.parse(props.getProperty("OCR_ARQUIVOS_PROCESSADOS")) || []; } catch(e) {}

  let padroesUsuario = {};
  try { padroesUsuario = JSON.parse(props.getProperty("OCR_PADROES_USUARIO")) || {}; } catch(e) {}

  // Se o array de memória ficar muito grande, limpa os mais antigos (limite do PropertiesService)
  if (arquivosProcessados.length > 500) arquivosProcessados = arquivosProcessados.slice(-300);

  const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO);
  let gavetasDeClientes = [];

  // 1. Coleta clientes normais
  let pastasClientes = pastaRaiz.getFoldersByName("01_CLIENTES");
  if (pastasClientes.hasNext()) {
      let clientesNormais = pastasClientes.next().getFolders();
      while(clientesNormais.hasNext()) gavetasDeClientes.push(clientesNormais.next());
  }

  // 2. Coleta clientes da Esteira Facebook
  let pastasEsteira = pastaRaiz.getFoldersByName("04_ESTEIRA_FACEBOOK");
  if (pastasEsteira.hasNext()) {
      let pastaExecucao = pastasEsteira.next().getFoldersByName("01_CLIENTES_EXECUCAO");
      if (pastaExecucao.hasNext()) {
          let clientesFace = pastaExecucao.next().getFolders();
          while(clientesFace.hasNext()) gavetasDeClientes.push(clientesFace.next());
      }
  }

  let achouMarcador = !marcadorPastaId;
  let chamadasIA = 0;
  let stats = { renomeados: 0, sincronizados: 0, aprendidos: 0, erros: 0 };
  let ultimoIdProcessado = null;

  // =========================================================================
  // ⚙️ LOOP DE PASTAS DOS CLIENTES
  // =========================================================================
  for (let c = 0; c < gavetasDeClientes.length; c++) {
    if (Date.now() - tempoInicio > limiteTempo) break;
    if (chamadasIA >= MAX_ARQUIVOS_POR_CICLO) break;

    let cliente = gavetasDeClientes[c];
    let idPasta = cliente.getId();

    if (!achouMarcador) {
        if (idPasta === marcadorPastaId) achouMarcador = true;
        continue;
    }

    let nomeCliente = cliente.getName();

    // Pula pastas que não são de clientes reais
    if (nomeCliente.includes("ANJOS") || nomeCliente.startsWith("00_")) continue;

    try {
        // 1. LER A ÁRVORE DO CLIENTE (Contexto)
        let arvore = lerArvoreDoCliente(cliente);

        // 2. APRENDER COM O USUÁRIO (Renomeações Manuais)
        let novosPadroes = detectarRenomeacaoManual(cliente);
        if (novosPadroes.length > 0) {
            novosPadroes.forEach(p => padroesUsuario[p.subcategoria] = p.padraoNome);
            stats.aprendidos += novosPadroes.length;
        }

        // 3. VARRER ARQUIVOS DA PASTA
        let pastasParaOlhar = [cliente];
        let subpastas = cliente.getFolders();
        while(subpastas.hasNext()) pastasParaOlhar.push(subpastas.next());

        for (let p = 0; p < pastasParaOlhar.length; p++) {
          if (chamadasIA >= MAX_ARQUIVOS_POR_CICLO) break;

          let arquivos = pastasParaOlhar[p].getFiles();

          while(arquivos.hasNext()) {
            if (chamadasIA >= MAX_ARQUIVOS_POR_CICLO) break;
            if (Date.now() - tempoInicio > limiteTempo) break;

            let arq = arquivos.next();
            let idArq = arq.getId();
            let nomeAtual = arq.getName();
            let mimeType = arq.getMimeType();
            let tamanhoBytes = arq.getSize();

            // Pulos de Segurança
            if (arquivosProcessados.includes(idArq)) continue;
            if (nomeAtual.match(/\[OCR\]|\[ESTUDADO\]|\[ERRO|\[MINUTA|PROCESSO ÍNTEGRO|ARVORE/i)) {
                // Se já tem tag nossa mas não tá na memória, adiciona na memória silenciosamente
                if (!arquivosProcessados.includes(idArq)) arquivosProcessados.push(idArq);
                continue;
            }
            if (!mimeType.includes("image/") && mimeType !== MimeType.PDF && mimeType !== MimeType.GOOGLE_DOCS) continue;

            console.log(`[OCR] Analisando novo arquivo: ${nomeAtual}`);

            try {
                // A) EXTRAÇÃO DE TEXTO
                let textoExtraido = "";
                let docTempId = null;

                if (mimeType === MimeType.GOOGLE_DOCS) {
                    textoExtraido = DocumentApp.openById(idArq).getBody().getText().substring(0, 4000);
                } else if (tamanhoBytes < 10000000) { // Limite de 10MB para OCR
                    try {
                        let arquivoTemp = { title: "Temp_OCR_" + idArq, mimeType: MimeType.GOOGLE_DOCS };
                        let docTemp = Drive.Files.copy(arquivoTemp, idArq, {ocr: true, ocrLanguage: 'pt-BR'}); 
                        docTempId = docTemp.id;
                        textoExtraido = DocumentApp.openById(docTempId).getBody().getText().substring(0, 4000); 
                    } finally {
                        if (docTempId) Drive.Files.remove(docTempId); // SEMPRE limpa o lixo
                    }
                }

                if (textoExtraido.trim().length < 15) {
                    arq.setName("[ERRO OCR] " + nomeAtual);
                    arquivosProcessados.push(idArq);
                    stats.erros++;
                    continue;
                }

                // B) CLASSIFICAÇÃO RÁPIDA (Força Bruta sem IA)
                let classificacao = classificarDocumento(textoExtraido, nomeAtual, tamanhoBytes);
                let nomeFinal = "";
                let usouIA = false;
                let sincronizacao = { idEncontrado: null, confianca: 0 };

                // Se não é Processo Íntegro nem Árvore clara, chama a IA para o pente-fino
                if (!classificacao.ehProcessoIntegro && !classificacao.ehArvore && classificacao.confianca < 80) {
                    let sistema = detectarSistemaJudicial(textoExtraido).sistema;
                    let prompt = montarPromptOCR(textoExtraido, nomeAtual, arvore, sistema);

                    let respostaIA = CHAMAR_IA_ESCRITORIO(prompt, "FLASH");
                    chamadasIA++;
                    usouIA = true;

                    if (respostaIA.includes("❌")) {
                        arq.setName(`[ERRO IA] ${nomeAtual}`);
                        console.log(`[OCR] Erro na IA: ${respostaIA}`);
                    } else {
                        // Extrai as tags da resposta da IA
                        let nomeSugerido = extrairTag(respostaIA, "NOME");
                        let catIA = extrairTag(respostaIA, "CATEGORIA");
                        let evtId = extrairTag(respostaIA, "EVENTO_ID");
                        let confIA = parseInt(extrairTag(respostaIA, "CONFIANCA")) || 0;

                        if (nomeSugerido) {
                            classificacao.categoria = catIA || classificacao.categoria;
                            nomeFinal = nomeSugerido;
                            if (evtId && evtId.length > 0) {
                                sincronizacao.idEncontrado = evtId;
                                sincronizacao.confianca = confIA;
                            }
                        }
                    }

                    Utilities.sleep(5000); // 🛡️ REGRA 4: Sleep obrigatório de 5s após a IA
                }

                // C) SINCRONIZAÇÃO FORÇA BRUTA (Se a IA não foi chamada ou não achou)
                if (!sincronizacao.idEncontrado && arvore.encontrada && !classificacao.ehProcessoIntegro && !classificacao.ehArvore) {
                    sincronizacao = sincronizarComArvore(textoExtraido, classificacao, arvore);
                }

                // D) GERADOR DE NOME (Se a IA não gerou o nomeFinal)
                if (nomeFinal === "") {
                    let padraoAprendido = null;
                    if (padroesUsuario[classificacao.subcategoria]) {
                        padraoAprendido = aplicarPadraoAprendido(classificacao.subcategoria, padroesUsuario, classificacao.pessoasEncontradas);
                    }
                    nomeFinal = gerarNomeFinal(classificacao, sincronizacao, arvore, padraoAprendido, nomeAtual);
                }

                // E) APLICAÇÃO FINAL
                if (nomeFinal !== "" && nomeFinal !== nomeAtual) {
                    let extensao = "";
                    if (nomeAtual.includes(".") && mimeType !== MimeType.GOOGLE_DOCS) {
                        extensao = nomeAtual.substring(nomeAtual.lastIndexOf("."));
                    }

                    // Limpeza de segurança no nome do arquivo
                    nomeFinal = nomeFinal.replace(/[\/\\]/g, "-").replace(/[:*?"<>|]/g, "").substring(0, 100);

                    arq.setName(nomeFinal.trim() + extensao);
                    arquivosProcessados.push(idArq);
                    stats.renomeados++;

                    // F) ATUALIZAR ÁRVORE COM O ✅
                    if (sincronizacao.idEncontrado && sincronizacao.confianca >= 70) {
                        atualizarArvoreComDocumento(arvore, sincronizacao, nomeFinal);
                        stats.sincronizados++;
                    }
                    console.log(`[OCR] Renomeado: ${nomeAtual} -> ${nomeFinal}`);
                }

            } catch(e) {
                console.log(`[OCR] Falha ao triturar ${nomeAtual}: ${e.message}`);
                arq.setName("[ERRO OCR] " + nomeAtual);
                arquivosProcessados.push(idArq);
                stats.erros++;
            }
          }
        }
    } catch(e) {
        console.log(`[OCR] Erro grave na pasta ${nomeCliente}: ${e.message}`);
    }

    ultimoIdProcessado = idPasta;
  }

  // =========================================================================
  // 💾 SALVAMENTO DE ESTADO E RELATÓRIO
  // =========================================================================
  props.setProperty("OCR_ARQUIVOS_PROCESSADOS", JSON.stringify(arquivosProcessados));
  if (Object.keys(padroesUsuario).length > 0) props.setProperty("OCR_PADROES_USUARIO", JSON.stringify(padroesUsuario));

  if (chamadasIA < MAX_ARQUIVOS_POR_CICLO && ultimoIdProcessado) {
      // Varreu tudo e não bateu no limite da IA, significa que acabou as pastas
      props.deleteProperty("OCR_ULTIMA_PASTA_ID");
      console.log("[OCR] Ciclo completo. O escritório inteiro foi varrido.");
  } else if (ultimoIdProcessado) {
      props.setProperty("OCR_ULTIMA_PASTA_ID", ultimoIdProcessado);
      console.log(`[OCR] Limite atingido. Pausado na pasta ID: ${ultimoIdProcessado}`);
  }

  if (!modoSilencioso && (stats.renomeados > 0 || stats.erros > 0)) {
      Browser.msgBox("🔎 TRITURADOR V3.0 (PERITO DIGITAL)", 
          `Análise concluída nesta rodada!\n\n` +
          `📄 Renomeados: ${stats.renomeados}\n` +
          `🔗 Sincronizados na Árvore: ${stats.sincronizados}\n` +
          `🧠 Padrões Aprendidos: ${stats.aprendidos}\n` +
          `🤖 Chamadas IA: ${chamadasIA}/${MAX_ARQUIVOS_POR_CICLO}\n` +
          `❌ Erros de Leitura: ${stats.erros}`, 
          Browser.Buttons.OK);
  } else if (!modoSilencioso) {
      Browser.msgBox("✅ AVISO", "A varredura foi feita, mas não há documentos novos pendentes de renomeação ou o ciclo está pausado.", Browser.Buttons.OK);
  }
}

