// 🔄 FÔLEGO INFINITO (VARREDURA CONTÍNUA)
// =========================================================================
function varreduraOCRContinua() {
  deletarTriggersAntigos('varreduraOCRContinua');

  const props = PropertiesService.getScriptProperties();
  let marcador = props.getProperty("OCR_ULTIMA_PASTA_ID");
  let inicioCiclo = parseInt(props.getProperty("OCR_CICLO_INICIO")) || 0;

  // Se não tem marcador e o último ciclo foi há menos de 2h, dorme.
  if (!marcador && (Date.now() - inicioCiclo < (2 * 60 * 60 * 1000))) {
      return; 
  }

  renomearArquivosComOCR(true);

  let novoMarcador = props.getProperty("OCR_ULTIMA_PASTA_ID");

  if (novoMarcador) {
      console.log("[OCR] Agendando continuação para daqui a 3 minutos...");
      ScriptApp.newTrigger('varreduraOCRContinua').timeBased().after(3 * 60 * 1000).create();
  } else {
      console.log("[OCR] Ciclo de OCR 100% completo.");
      props.setProperty("OCR_CICLO_INICIO", Date.now().toString());
  }
}


