// 🧠 FUNÇÕES AUXILIARES DE INTELIGÊNCIA FORENSE
// =========================================================================

function lerArvoreDoCliente(pastaCliente) {
    let obj = { encontrada: false, cnj: "", tribunal: "", eventos: [], textoCompleto: "", arquivoId: null };

    // Busca a Árvore na raiz e na 03_Andamentos
    let arquivosPossiveis = [];
    let arquivosRaiz = pastaCliente.getFiles();
    while (arquivosRaiz.hasNext()) arquivosPossiveis.push(arquivosRaiz.next());

    let gaveta03 = pastaCliente.getFoldersByName("03_Andamentos_Despachos");
    if (gaveta03.hasNext()) {
        let arqGaveta = gaveta03.next().getFiles();
        while (arqGaveta.hasNext()) arquivosPossiveis.push(arqGaveta.next());
    }

    let arvoreFile = null;
    for (let arq of arquivosPossiveis) {
        let n = arq.getName().toUpperCase();
        if (n.includes("ARVORE") || n.includes("MOVIMENTA")) {
            arvoreFile = arq;
            break;
        }
    }

    if (arvoreFile && arvoreFile.getMimeType() === MimeType.GOOGLE_DOCS) {
        try {
            obj.arquivoId = arvoreFile.getId();
            obj.textoCompleto = DocumentApp.openById(obj.arquivoId).getBody().getText();
            obj.encontrada = true;

            // Extrai CNJ
            let matchCNJ = obj.textoCompleto.match(/(\d{7}-\d{2}\.\d{4}\.\d{1}\.\d{2,3}\.\d{4})/);
            if (matchCNJ) obj.cnj = matchCNJ[1];

            // Tenta extrair eventos genéricos via Regex
            let matchesEventos = [...obj.textoCompleto.matchAll(/(\d{4,15})\s*-\s*([^\n]+)/g)];
            matchesEventos.forEach(m => {
                obj.eventos.push({ id: m[1], descricao: m[2].trim() });
            });

        } catch(e) { console.log("[OCR] Erro ao ler árvore interna: " + e.message); }
    }

    return obj;
}

function classificarDocumento(texto, nomeOriginal, tamanhoBytes) {
    let result = {
        categoria: "OUTROS", subcategoria: "Documento",
        ehProcessoIntegro: false, ehArvore: false, ehPrintTela: false,
        pessoasEncontradas: [], cnjEncontrado: "", idEventoProvavel: "", confianca: 0
    };

    let txt = texto.toLowerCase();

    // 1. É um Processo Íntegro? (Longo, Vários docs dentro)
    if (tamanhoBytes > 500000 && txt.includes("petição inicial") && txt.includes("sentença")) {
        result.ehProcessoIntegro = true;
        result.categoria = "PROCESSO_INTEGRO";
        result.confianca = 90;
    }

    // 2. É uma Árvore?
    if (txt.includes("polo ativo") && txt.includes("juntada de") && (txt.match(/\d{2}\/\d{2}\/\d{4}/g) || []).length > 5) {
        result.ehArvore = true;
        result.categoria = "ARVORE_MOVIMENTACOES";
        result.confianca = 95;
    }

    // 3. Tem CNJ?
    let cnj = texto.match(/(\d{7}-\d{2}\.\d{4}\.\d{1}\.\d{2,3}\.\d{4})/);
    if (cnj) result.cnjEncontrado = cnj[1];

    // 4. Classificação Básica de Subcategoria
    if (txt.includes("procuração ad judicia")) result.subcategoria = "Procuração";
    else if (txt.includes("carteira nacional de habilitação")) result.subcategoria = "CNH";
    else if (txt.includes("hipossuficiência") || txt.includes("justiça gratuita")) result.subcategoria = "Hipossuficiência";
    else if (txt.includes("contestação")) result.subcategoria = "Contestação";
    else if (txt.includes("petição inicial")) result.subcategoria = "Petição Inicial";

    return result;
}

function sincronizarComArvore(textoDoc, classificacao, arvore) {
    let sync = { idEncontrado: null, confianca: 0 };
    if (!arvore || !arvore.encontrada || arvore.eventos.length === 0) return sync;

    // Busca matches diretos de IDs da árvore dentro do texto do documento
    for (let evt of arvore.eventos) {
        if (evt.id && evt.id.length > 5 && textoDoc.includes(evt.id)) {
            sync.idEncontrado = evt.id;
            sync.confianca = 95;
            break;
        }
    }
    return sync;
}

function detectarRenomeacaoManual(pastaCliente) {
    let padroes = [];
    let arquivos = pastaCliente.searchFiles("trashed = false");
    while(arquivos.hasNext()) {
        let nome = arquivos.next().getName();
        // Se o nome não tem tags automáticas, mas tem um padrão estruturado com hífen
        if (!nome.match(/\[OCR\]|\[ESTUDADO\]/i) && nome.includes(" - ") && nome.length > 10) {
            let partes = nome.split(" - ");
            let tipo = partes[0].trim().toLowerCase(); // Ex: "Procuração"
            if (tipo === "cnh" || tipo === "rg" || tipo === "procuração") {
                padroes.push({ subcategoria: tipo, padraoNome: partes[0].trim() + " - [NOME]" });
            }
        }
    }
    return padroes;
}

function aplicarPadraoAprendido(subcategoria, padroesUsuario, pessoas) {
    let padrao = padroesUsuario[subcategoria.toLowerCase()];
    if (padrao) {
        let nomePessoa = pessoas.length > 0 ? pessoas[0] : "Cliente";
        return padrao.replace("[NOME]", nomePessoa);
    }
    return null;
}

function gerarNomeFinal(classificacao, sincronizacao, arvore, padraoAprendido, nomeOriginal) {
    if (classificacao.ehProcessoIntegro) {
        let dataHj = Utilities.formatDate(new Date(), "GMT-3", "dd_MM_yyyy");
        let cnj = classificacao.cnjEncontrado || "CNJ_Nao_Identificado";
        return `PROCESSO ÍNTEGRO - ${cnj} - ${dataHj}`;
    }

    if (classificacao.ehArvore) {
        if (nomeOriginal.toUpperCase().includes("ARVORE")) return nomeOriginal; // Não mexe se já tá certo
        return `ARVORE - Extrato de Movimentações`;
    }

    if (sincronizacao.idEncontrado && sincronizacao.confianca >= 70) {
        return `[OCR] Evt.${sincronizacao.idEncontrado} - ${classificacao.subcategoria}`;
    }

    if (padraoAprendido) {
        return `[OCR] ${padraoAprendido}`;
    }

    return `[OCR] ${classificacao.subcategoria}`;
}

function atualizarArvoreComDocumento(arvore, sincronizacao, nomeNovo) {
    if (!arvore.arquivoId) return;
    try {
        let doc = DocumentApp.openById(arvore.arquivoId);
        let body = doc.getBody();
        let textoCompleto = body.getText();

        let idBusca = sincronizacao.idEncontrado;
        if (!textoCompleto.includes(`✅[ARQUIVO: ${nomeNovo}]`)) {
            // Usa replaceText para injetar a confirmação visual na frente do ID do evento
            body.replaceText(`(${idBusca}[^\\n]+)`, `$1 ✅[ARQUIVO: ${nomeNovo}]`);
            doc.saveAndClose();
        }
    } catch(e) { console.log("[OCR] Falha ao carimbar árvore: " + e.message); }
}

function extrairTag(texto, tag) {
    let m = texto.match(new RegExp("\\[" + tag + "\\]([\\s\\S]*?)(?:\\[\\/" + tag + "\\])", "i"));
    return m ? m[1].replace(/^\*\*|\*\*$/g, "").trim() : null;
}

function detectarSistemaJudicial(texto) {
  let txt = texto.substring(0, 800).toLowerCase();
  let result = { sistema: "GENERICO" };
  if (txt.includes("eproc")) result.sistema = "EPROC";
  else if (txt.includes("pje") || txt.includes("processo judicial eletrônico")) result.sistema = "PJE";
  else if (txt.includes("seeu")) result.sistema = "SEEU";
  return result;
}

function montarPromptOCR(textoExtraido, nomeOriginal, arvore, sistemaDetectado) {
    let arvoreTxt = "";
    if (arvore && arvore.eventos.length > 0) {
        arvoreTxt = `ÁRVORE DO PROCESSO:\nOs últimos eventos do processo são:\n` + 
        arvore.eventos.slice(0,10).map(e => e.id + ' - ' + e.descricao).join('\n') +
        `\nPERGUNTA ADICIONAL: Este documento que você está lendo corresponde a algum dos eventos acima? Se sim, qual o ID numérico exato do evento?`;
    }

    return `Você é o Perito Forense Digital do escritório Dr. Lucas Semim (OAB/MG 222.539).
    Seu trabalho é classificar documentos jurídicos com precisão máxima.

    DOCUMENTO ANALISADO:
    Nome original: '${nomeOriginal}'
    Texto extraído (resumo):
    '${textoExtraido}'

    ${arvoreTxt}

    INSTRUÇÕES:
    1. Identifique a CATEGORIA (PESSOAL, OAB, PROCESSUAL, PROVA).
    2. Identifique o NOVO NOME sugerido para o arquivo (ex: Procuração - João Silva, CNH - Maria, Contestação).

    RESPONDA ESTRITAMENTE NESTE FORMATO (sem texto extra):
    [NOME][OCR] TIPO DO DOC - NOME DA PESSOA[/NOME]
    [CATEGORIA]TIPO_CATEGORIA[/CATEGORIA]
    [EVENTO_ID]ID_DO_EVENTO_OU_VAZIO[/EVENTO_ID]
    [CONFIANCA]0_A_100[/CONFIANCA]`;
}

function deletarTriggersAntigos(nomeFuncao) {
  let triggers = ScriptApp.getProjectTriggers();
  for (let i = 0; i < triggers.length; i++) {
    if (triggers[i].getHandlerFunction() === nomeFuncao) ScriptApp.deleteTrigger(triggers[i]);
  }
}

