// =========================================================================
function lerArvoreDeProcessos(modoSilencioso = false) {
  const tempoInicio = Date.now(); 
  const limiteTempo = 270000; // 4.5 min

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName("Dashboard Principal") || ss.getSheetByName("PROCESSOS");

  if (!sheet) {
      if (!modoSilencioso) Browser.msgBox("❌ ERRO", "O Radar só roda no Dashboard Principal.", Browser.Buttons.OK);
      return;
  }

  const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO);
  let pasta01;
  try { pasta01 = pastaRaiz.getFoldersByName("01_CLIENTES").next(); } catch(e) { return; }

  if (!modoSilencioso) sheet.getRange("A1").setValue("⏳ Radar escaneando Tribunais...").setFontColor("#E67E22");

  const dadosPlanilha = sheet.getDataRange().getValues();
  const props = PropertiesService.getScriptProperties();

  // Lendo marcadores de posição
  let ultimaPastaLida = parseInt(props.getProperty("ARVORE_ULTIMA_LINHA")) || 2;
  let filaUrgente = [];
  let filaProcessamento = [];

  // 🗺️ REGRA GEOGRÁFICA: Loop de dados começa na Linha 3 (Índice 2)
  for (let i = 2; i < dadosPlanilha.length; i++) {
    let nomeCliente = String(dadosPlanilha[i][1]); // Col B
    let urlPasta = String(dadosPlanilha[i][4]);    // Col E
    let prazoFatal = String(dadosPlanilha[i][7]);  // Col H

    if (nomeCliente.includes("CLIENTE:") && urlPasta.includes("drive.google.com")) {
        let idPasta = urlPasta.split("folders/")[1]?.split("?")[0];
        if (!idPasta) continue;

        let obj = { linha: i + 1, nome: nomeCliente.replace("CLIENTE: ", "").trim(), id: idPasta, isUrgente: false };

        // Verifica se é urgente (Prazo nos próximos 7 dias)
        if (prazoFatal.match(/\d{2}\/\d{2}\/\d{4}/)) {
            let p = prazoFatal.match(/(\d{2})\/(\d{2})\/(\d{4})/);
            let d = new Date(p[3], parseInt(p[2])-1, p[1]);
            let hj = new Date(); hj.setHours(0,0,0,0);
            let dias = (d - hj) / (1000*60*60*24);
            if (dias >= 0 && dias <= 7) obj.isUrgente = true;
        }

        if (obj.isUrgente) filaUrgente.push(obj);
        else filaProcessamento.push(obj);
    }
  }

  // Organiza: Urgentes Primeiro, depois os normais a partir do marcador
  let filaFinal = [];
  filaUrgente.forEach(u => filaFinal.push(u));

  let normaisFiltrados = filaProcessamento.filter(p => p.linha > ultimaPastaLida);
  normaisFiltrados.forEach(n => filaFinal.push(n));

  let arvoresProcessadas = 0;
  let ultimaLinhaLidaNesteCiclo = ultimaPastaLida;

  // =========================================================================
  // ⚙️ 2. LOOP DE PROCESSAMENTO CIRÚRGICO
  // =========================================================================
  for (let alvo of filaFinal) {
    if (Date.now() - tempoInicio > limiteTempo) {
        console.log("[ARVORE] Limite de tempo atingido. Interrompendo lote.");
        break;
    }

    // 🛡️ REGRA COTA DE IA: Máximo de 5 processos por rodada
    if (arvoresProcessadas >= 5) break; 

    let linhaAlvo = alvo.linha;
    let dataUltimaLeitura = dadosPlanilha[linhaAlvo - 1][16]; // Col Q
    let proximaAcaoExistente = dadosPlanilha[linhaAlvo - 1][13]; // Col N

    try {
        let clientePasta = DriveApp.getFolderById(alvo.id);

        // Camada de Busca Inteligente
        let docEncontrado = localizarDocumentoArvore(clientePasta);

        if (!docEncontrado) {
            // Se não encontrou o doc da árvore, nem gasta cota da IA. Avisa e pula.
            sheet.getRange(linhaAlvo, 17).setValue("⚠️ SEM DOC DE ÁRVORE");
            continue;
        }

        let ultimaModDrive = docEncontrado.getLastUpdated();
        let precisaLer = true;
        if (dataUltimaLeitura instanceof Date && ultimaModDrive <= dataUltimaLeitura && !alvo.isUrgente) {
            precisaLer = false;
        }

        if (precisaLer) {
            console.log(`[ARVORE] Lendo tribunal: ${alvo.nome}`);
            sheet.getRange("A1").setValue(`⏳ Lendo Árvore de: ${alvo.nome.substring(0, 15)}...`).setFontColor("#E67E22");
            SpreadsheetApp.flush();

            let textoExtraido = lerTextoArquivo(docEncontrado, 10000);
            if (textoExtraido.trim() === "") continue;

            // 🔥 NOVIDADE V8.2: Extrai o CNJ PRIMEIRO para garantir a detecção do tribunal
            let matchCNJ = textoExtraido.match(/(\d{7}-\d{2}\.\d{4}\.\d{1}\.\d{2,3}\.\d{4})/);
            let cnjEncontrado = matchCNJ ? matchCNJ[1] : "";

            let sistemaJudicial = detectarSistemaJudicial(textoExtraido, cnjEncontrado);
            let dadosExtraidos = extrairDadosDaArvore(textoExtraido, sistemaJudicial, cnjEncontrado);

            // Delegando a formatação pesada para a IA com prompt rigoroso
            let dataHojeStr = Utilities.formatDate(new Date(), "GMT-3", "dd/MM/yyyy");
            let prompt = montarPromptArvore(textoExtraido, sistemaJudicial.sistema, dataHojeStr, proximaAcaoExistente);

            let respostaIA = CHAMAR_IA_ESCRITORIO(prompt, "FLASH");

            if (respostaIA.includes("❌")) {
                sheet.getRange(linhaAlvo, 17).setValue(respostaIA.substring(0, 50)); // Expõe o erro real
            } else {
                let tagsIA = extrairTodasAsTags(respostaIA);
                // Mescla os dados (Regex rápido + IA profunda)
                if (!dadosExtraidos.cnj) dadosExtraidos.cnj = tagsIA.cnj;
                if (!dadosExtraidos.prazoDetectado) dadosExtraidos.prazoDetectado = tagsIA.prazo_fatal;
                if (!dadosExtraidos.parteContraria) dadosExtraidos.parteContraria = tagsIA.parte_contraria;
                if (!dadosExtraidos.classeProcessual) dadosExtraidos.classeProcessual = tagsIA.classe_processual;
                if (!dadosExtraidos.valorCausa) dadosExtraidos.valorCausa = tagsIA.valor_causa;

                // IA entrega os andamentos já mastigados e formatados
                if (tagsIA.andamentos_recentes !== "Não extraído.") dadosExtraidos.andamentosRecentes = tagsIA.andamentos_recentes;

                dadosExtraidos.proximaAcaoNova = tagsIA.proxima_acao;
                dadosExtraidos.nivelUrgencia = tagsIA.nivel_urgencia;
            }

            // 💉 INJEÇÃO NAS COLUNAS CORRETAS
            if (dadosExtraidos.cnj && dadosExtraidos.cnj !== "Não extraído.") sheet.getRange(linhaAlvo, 9).setValue(dadosExtraidos.cnj);
            if (dadosExtraidos.classeProcessual && dadosExtraidos.classeProcessual !== "Não extraído." && String(dadosPlanilha[linhaAlvo-1][6]) === "") sheet.getRange(linhaAlvo, 7).setValue(dadosExtraidos.classeProcessual);
            if (dadosExtraidos.parteContraria && dadosExtraidos.parteContraria !== "Não extraído." && String(dadosPlanilha[linhaAlvo-1][11]) === "") sheet.getRange(linhaAlvo, 12).setValue(dadosExtraidos.parteContraria);
            if (dadosExtraidos.valorCausa && dadosExtraidos.valorCausa.includes("R$") && String(dadosPlanilha[linhaAlvo-1][18]) === "") sheet.getRange(linhaAlvo, 19).setValue(dadosExtraidos.valorCausa);

            if (dadosExtraidos.prazoDetectado && dadosExtraidos.prazoDetectado.match(/\d{2}\/\d{2}\/\d{4}/)) {
                sheet.getRange(linhaAlvo, 8).setValue(dadosExtraidos.prazoDetectado);
            }

            if (dadosExtraidos.andamentosRecentes && dadosExtraidos.andamentosRecentes.length > 5) {
                sheet.getRange(linhaAlvo, 16).setValue(dadosExtraidos.andamentosRecentes);
            }

            let celulaSist = sheet.getRange(linhaAlvo, 15);
            let label = `🖥️ ${sistemaJudicial.sistema}\n📍 ${sistemaJudicial.tribunal}`;
            if (dadosExtraidos.urlTribunal && dadosExtraidos.urlTribunal.includes("http")) {
                celulaSist.setFormula(`=HYPERLINK("${dadosExtraidos.urlTribunal}"; "${label}\n\n➡️ ACESSAR AUTOS")`);
            } else {
                celulaSist.setValue(label);
            }

            if (dadosExtraidos.proximaAcaoNova && dadosExtraidos.proximaAcaoNova !== "Não extraído." && dadosExtraidos.proximaAcaoNova.length > 10) {
                sheet.getRange(linhaAlvo, 14).setValue(dadosExtraidos.proximaAcaoNova);
            }

            sheet.getRange(linhaAlvo, 17).setValue(new Date()); // Carimbo Leitura

            // Sinfonia com outros scripts
            if (!modoSilencioso || dadosExtraidos.nivelUrgencia === "CRITICA") {
                acionarSinfoniaAposArvore(sheet, linhaAlvo, dadosExtraidos.nivelUrgencia);
            }

            arvoresProcessadas++;
            Utilities.sleep(5000); // 🛡️ REGRA COTA: Respiro de 5 segundos vital após a IA
        }

        if (!alvo.isUrgente) ultimaLinhaLidaNesteCiclo = linhaAlvo;

    } catch (e) {
        console.log(`[ARVORE] Erro ao processar ${alvo.nome}: ${e.message}`);
    }
  }

  // Atualiza Marcador
  if (ultimaLinhaLidaNesteCiclo >= sheet.getLastRow()) ultimaLinhaLidaNesteCiclo = 2;
  props.setProperty("ARVORE_ULTIMA_LINHA", ultimaLinhaLidaNesteCiclo.toString());

  sheet.getRange("A1").setValue("DATA ANÁLISE").setFontColor("#FFFFFF");
  console.log(`[ARVORE] Ciclo concluído. ${arvoresProcessadas} processados. Parou na linha ${ultimaLinhaLidaNesteCiclo}`);

  if (!modoSilencioso && arvoresProcessadas > 0) {
      Browser.msgBox("🌳 RADAR V8.2", arvoresProcessadas + " processos escaneados!\nSistemas e Expedientes alinhados cirurgicamente.", Browser.Buttons.OK);
  } else if (!modoSilencioso) {
      Browser.msgBox("✅ TUDO ATUALIZADO", "O Radar varreu os processos mas não detectou andamentos novos nas pastas.", Browser.Buttons.OK);
  }
}

