// =========================================================================
// 🔎 4. BUSCA INTELIGENTE EM 4 CAMADAS
// =========================================================================
function localizarDocumentoArvore(pastaCliente) {
  let docsEncontrados = [];

  function varrerPasta(pasta) {
     let arquivos = pasta.getFiles();
     while (arquivos.hasNext()) docsEncontrados.push(arquivos.next());
  }

  varrerPasta(pastaCliente);
  let gavetas = pastaCliente.getFoldersByName("03_Andamentos_Despachos");
  if (gavetas.hasNext()) varrerPasta(gavetas.next());

  if (docsEncontrados.length === 0) return null;

  // CAMADA 1: Keywords no nome
  const keywords = ["ARVORE", "MOVIMENTACAO", "MOVIMENTAÇÃO", "ANDAMENTO", "CONSULTA PROCESSUAL", "EXTRATO PROCESSUAL", "HISTÓRICO"];
  for (let arq of docsEncontrados) {
      let n = arq.getName().toUpperCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
      for (let k of keywords) {
          if (n.includes(k) && !n.includes("DOSSIE") && !n.includes("MINUTA")) return arq;
      }
  }

  // CAMADA 2: Arquivo [OCR] com conteúdo judicial
  for (let arq of docsEncontrados) {
      if (arq.getName().includes("[OCR]")) {
          try {
             let txt = lerTextoArquivo(arq, 300);
             if (txt.match(/(\d{7}-\d{2}\.\d{4}\.\d{1}\.\d{2,3}\.\d{4})/)) return arq;
          } catch(e) {}
      }
  }

  // CAMADA 3: Documento recente com CNJ
  docsEncontrados.sort((a, b) => b.getLastUpdated() - a.getLastUpdated());
  let tentativas = 0;
  for (let arq of docsEncontrados) {
      if (tentativas > 4) break; 
      if (arq.getMimeType() === MimeType.GOOGLE_DOCS && !arq.getName().includes("DOSSIÊ") && !arq.getName().includes("MINUTA")) {
          try {
              let txt = DocumentApp.openById(arq.getId()).getBody().getText().substring(0, 300);
              if (txt.match(/(\d{7}-\d{2}\.\d{4}\.\d{1}\.\d{2,3}\.\d{4})/)) return arq;
          } catch(e) {}
          tentativas++;
      }
  }

  return null; 
}

function lerTextoArquivo(arquivo, limite) {
  try {
      if (arquivo.getMimeType() === MimeType.GOOGLE_DOCS) {
          return DocumentApp.openById(arquivo.getId()).getBody().getText().substring(0, limite);
      } else if (arquivo.getMimeType() === MimeType.PDF && arquivo.getSize() < 5000000) {
          let temp = Drive.Files.copy({title: "Temp", mimeType: MimeType.GOOGLE_DOCS}, arquivo.getId(), {ocr: true, ocrLanguage: 'pt-BR'});
          let txt = DocumentApp.openById(temp.id).getBody().getText().substring(0, limite);
          Drive.Files.remove(temp.id);
          return txt;
      }
  } catch (e) { console.log("[ARVORE] Erro ao ler arquivo " + arquivo.getName()); }
  return "";
}

