// 🧠 5. DETECÇÃO E EXTRAÇÃO
// =========================================================================
function detectarSistemaJudicial(texto, cnjEncontrado) {
  let txt = texto.substring(0, 800).toLowerCase();
  let result = { sistema: "GENERICO", tribunal: "TRIBUNAL", grau: "1", area: "CIVEL" };

  // 🔥 V8.2: Tenta a precisão absoluta do CNJ primeiro
  if (cnjEncontrado && cnjEncontrado !== "") {
      let partes = cnjEncontrado.split(".");
      if (partes.length >= 4) {
          let segmento = partes[2] + "." + partes[3];
          const mapaTribunais = {
              "8.13": {s: "TJMG_PJE_1GRAU", t: "TJMG"},
              "8.26": {s: "TJSP_ESAJ", t: "TJSP"},
              "8.19": {s: "TJRJ_PJE", t: "TJRJ"},
              "8.08": {s: "TJES_EPROC", t: "TJES"},
              "8.24": {s: "TJSC_EPROC", t: "TJSC"},
              "8.05": {s: "TJBA_PJE", t: "TJBA"},
              "5.06": {s: "TRT6_PJE", t: "TRT6", a: "TRABALHISTA"},
              "4.06": {s: "TRF6_EPROC", t: "TRF6", a: "FEDERAL"}
          };

          if (mapaTribunais[segmento]) {
              result.sistema = mapaTribunais[segmento].s;
              result.tribunal = mapaTribunais[segmento].t;
              if (mapaTribunais[segmento].a) result.area = mapaTribunais[segmento].a;

              // Ajuste fino para 2 Grau do TJMG
              if (segmento === "8.13" && (txt.includes("des.(a)") || txt.includes("câmara") || txt.includes("cacri"))) {
                  result.sistema = "TJMG_PJE_2GRAU"; result.grau = "2";
              }
              return result;
          }
      }
  }

  // Fallback para o texto se o CNJ falhou ou não estiver no mapa
  if (txt.includes("eproc") || txt.includes("procecomciv") || txt.includes(".8.08.")) {
      result.sistema = "TJES_EPROC"; result.tribunal = "TJES";
  } else if (txt.includes(".8.13.") || txt.includes("tjmg")) {
      if (txt.includes("des.(a)") || txt.includes("câmara")) { result.sistema = "TJMG_PJE_2GRAU"; result.tribunal = "TJMG"; result.grau = "2"; }
      else { result.sistema = "TJMG_PJE_1GRAU"; result.tribunal = "TJMG"; }
  } else if (txt.includes(".5.") || txt.includes("trt") || txt.includes("reclamante")) {
      result.sistema = "TRT_PJE"; result.tribunal = "Justiça do Trabalho"; result.area = "TRABALHISTA";
  } else if (txt.includes("trf") || txt.includes(".4.") || txt.includes(".6.")) {
      result.sistema = "TRF_EPROC"; result.tribunal = "Justiça Federal"; result.area = "FEDERAL";
  } else if (txt.includes("seeu") || txt.includes("execuções criminais")) {
      result.sistema = "SEEU"; result.tribunal = "Vara de Execuções"; result.area = "EXECUCAO_PENAL";
  }

  return result;
}

function extrairDadosDaArvore(texto, sisDetectado, cnjEncontrado) {
  let dados = { cnj: cnjEncontrado, tribunal: sisDetectado.tribunal, valorCausa: "", parteContraria: "", urlTribunal: "", andamentosRecentes: "", hayNovidade: true };

  let matchValor = texto.match(/[Vv]alor da causa[:\s]+R\$\s*([\d.,]+)/);
  if (matchValor) dados.valorCausa = "R$ " + matchValor[1];

  let matchUrl = texto.match(/https?:\/\/[^\s\n]+(?:pje|eproc|tjmg|tjes|trf|seeu)[^\s\n]*/i);
  if (matchUrl) dados.urlTribunal = matchUrl[0];

  return dados;
}

