  } else {
      regrasSistema = "Identifique fase. PRAZO_FATAL: calcule prazo vigente e aplique D-1 (segurança).";
  }

  return `Você é um Jurista Sênior do escritório Dr. Lucas Semim (OAB/MG 222.539).
  Analise a árvore de movimentações judiciais abaixo.
  Sistema Detectado: ${sistema}. Hoje é ${dataHoje}.

  ÁRVORE DE MOVIMENTAÇÕES:
  '${texto}'

  ESTRATÉGIA ATUAL DO ESCRITÓRIO:
  '${proximaAcao}'

  INSTRUÇÕES ESPECÍFICAS PARA ESTE SISTEMA:
  ${regrasSistema}

  Responda ESTRITAMENTE com as TAGS abaixo:
  [CNJ]...[/CNJ]
  [TRIBUNAL]...[/TRIBUNAL]
  [ORGAO]...[/ORGAO]
  [VALOR_CAUSA]...[/VALOR_CAUSA]
  [PARTE_CONTRARIA]...[/PARTE_CONTRARIA]
  [CLASSE_PROCESSUAL]...[/CLASSE_PROCESSUAL]
  [PRAZO_FATAL]...[/PRAZO_FATAL] (Apenas a data calculada em DD/MM/AAAA ou Vazio)
  [DIAS_RESTANTES]...[/DIAS_RESTANTES]
  [ANDAMENTOS_RECENTES]...[/ANDAMENTOS_RECENTES] (CRÍTICO: Resuma os 5 últimos andamentos do processo. PROIBIDO RETORNAR APENAS NÚMEROS DE EVENTO. Extraia a ação real. Inicie com emoji. Exemplo correto: "📝 14/04/2026 — Conclusos à relatoria". Formato rigoroso: [EMOJI] [DATA] — [RESUMO TEXTUAL DA AÇÃO])
  [STATUS_ATUAL]...[/STATUS_ATUAL]
  [PROXIMA_ACAO]...[/PROXIMA_ACAO] (Atualize a estratégia se necessário)
  [NIVEL_URGENCIA]...[/NIVEL_URGENCIA] (Responda APENAS: CRITICA, ALTA, NORMAL, BAIXA)
  [URL_TRIBUNAL]...[/URL_TRIBUNAL]`;
}

function extrairTodasAsTags(texto) {
  const tags = ["CNJ", "TRIBUNAL", "ORGAO", "VALOR_CAUSA", "PARTE_CONTRARIA", "CLASSE_PROCESSUAL", 
                "PRAZO_FATAL", "DIAS_RESTANTES", "ANDAMENTOS_RECENTES", "STATUS_ATUAL", "PROXIMA_ACAO", "NIVEL_URGENCIA", "URL_TRIBUNAL"];
  let result = {};
  tags.forEach(tag => {
      let m = texto.match(new RegExp("\\[" + tag + "\\]([\\s\\S]*?)(?:\\[\\/" + tag + "\\])", "i"));
      result[tag.toLowerCase()] = m && m[1] ? m[1].replace(/^\*\*|\*\*$/g, "").trim() : "Não extraído.";
  });
  return result;
}

