// =========================================================================
// 🌡️ 1. MOTOR PRINCIPAL DE TERMÔMETROS
// =========================================================================
function atualizarFasesProcessuais(modoSilencioso = false) {
  const tempoInicio = Date.now(); 
  const limiteTempo = 270000; // 4.5 min

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  let sheet = ss.getSheetByName("Dashboard Principal") || ss.getSheetByName("PROCESSOS");

  if (!sheet) {
      if (!modoSilencioso) Browser.msgBox("❌ ERRO", "O Sentinela só roda no Dashboard Principal.", Browser.Buttons.OK);
      return;
  }

  const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO);
  let pasta01;
  try { pasta01 = pastaRaiz.getFoldersByName("01_CLIENTES").next(); } catch(e) { return; }

  if (!modoSilencioso) sheet.getRange("A1").setValue("⏳ Calibrando Termômetros...").setFontColor("#8E44AD");
  SpreadsheetApp.flush();

  const dadosPlanilha = sheet.getDataRange().getValues();
  const props = PropertiesService.getScriptProperties();

  let ultimoIndex = parseInt(props.getProperty("FASES_ULTIMA_PASTA_ID")) || 2;
  let fila = [];

  for (let i = 1; i < dadosPlanilha.length; i++) {
    let nomeCliente = String(dadosPlanilha[i][1]); 
    let urlPasta = String(dadosPlanilha[i][4]);    

    if (nomeCliente.includes("CLIENTE:") && urlPasta.includes("drive.google.com")) {
        let idPasta = urlPasta.split("folders/")[1]?.split("?")[0];
        if (!idPasta) continue;

        let obj = { linha: i + 1, nome: nomeCliente.replace("CLIENTE: ", "").trim(), id: idPasta, prioridade: 3 };
        let prioridadeCalculada = calcularPrioridade(dadosPlanilha[i]);

        if (prioridadeCalculada === "PULAR") continue;

        obj.prioridade = prioridadeCalculada;
        fila.push(obj);
    }
  }

  fila.sort((a, b) => a.prioridade - b.prioridade);
  let filaFinal = fila.filter(f => f.prioridade === 1 || f.linha > ultimoIndex);
  if (filaFinal.length === 0) filaFinal = fila; 

  let processados = 0;
  let urgentesProcessados = 0;
  let ultimaLinhaProcessada = ultimoIndex;

  // =========================================================================
  // ⚙️ 3. LOOP DE PROCESSAMENTO
  // =========================================================================
  for (let alvo of filaFinal) {
    if (Date.now() - tempoInicio > limiteTempo) break;
    if (processados >= 5 && alvo.prioridade > 1) break;

    let linhaAlvo = alvo.linha;
    let dadosLinha = dadosPlanilha[linhaAlvo - 1];

    try {
        let pastaCliente = DriveApp.getFolderById(alvo.id);

        sheet.getRange("A1").setValue(`🌡️ Calculando Fase: ${alvo.nome.substring(0, 15)}...`).setFontColor("#8E44AD");
        sheet.getRange(linhaAlvo, 18).setValue("⏳ Calculando...");
        SpreadsheetApp.flush();

        let contexto = montarContextoCliente(pastaCliente, dadosLinha);
        if (contexto.textoArvore === "" && contexto.textoDossie === "") {
            sheet.getRange(linhaAlvo, 18).setValue("⚠️ Sem documentos base");
            continue;
        }

        let dataHojeStr = Utilities.formatDate(new Date(), "GMT-3", "dd/MM/yyyy");
        let prompt = montarPromptFase(contexto, dataHojeStr);

        let respostaIA = CHAMAR_IA_ESCRITORIO(prompt, "FLASH"); 

        // 🔥 A CURA: AGORA ELE MOSTRA O ERRO REAL EM VEZ DE MASCARAR 🔥
        if (respostaIA.includes("❌")) {
            sheet.getRange(linhaAlvo, 18).setValue(respostaIA.substring(0, 50) + "..."); // Escreve o erro real da IA na célula
            console.log(`[FASES] Erro da IA no cliente ${alvo.nome}: ${respostaIA}`);
            continue;
        }

        const extrair = (tag) => {
            let m = respostaIA.match(new RegExp("\\[" + tag + "\\]([\\s\\S]*?)(?:\\[\\/" + tag + "\\])", "i"));
            return m ? m[1].replace(/^\*\*|\*\*$/g, "").trim() : "Não extraído";
        };

        let fase = extrair("FASE");
        let percStr = extrair("PERC");
        let valor = extrair("VALOR");
        let urgencia = extrair("URGENCIA");
        let mudancaDetectada = extrair("MUDANCA_DETECTADA");

        let percNum = parseInt(percStr.replace(/\D/g, "")) || 0;

        let barraCompleta = construirBarraFase(fase, percNum, contexto.areaDetectada, urgencia, contexto.prazoFatal);
        sheet.getRange(linhaAlvo, 18).setValue(barraCompleta); 

        if (valor !== "Não extraído" && valor.includes("R$") && String(dadosLinha[18]) === "") {
            sheet.getRange(linhaAlvo, 19).setValue(valor); 
        }

        if (mudancaDetectada === "SIM" && urgencia === "CRITICA" && typeof processarAnaliseUnica === "function") {
            try { processarAnaliseUnica(sheet, linhaAlvo, "CLIENTE: " + alvo.nome, true, pastaCliente); } catch(e){}
        }

        processados++;
        if (alvo.prioridade === 1) urgentesProcessados++;
        ultimaLinhaProcessada = linhaAlvo;

        Utilities.sleep(5000); 

    } catch (e) {
        sheet.getRange(linhaAlvo, 18).setValue("❌ Erro no Script: " + e.message.substring(0, 30));
        console.log(`[FASES] Erro script ${alvo.nome}: ${e.message}`);
    }
  }

  if (ultimaLinhaProcessada >= sheet.getLastRow()) ultimaLinhaProcessada = 2;
  props.setProperty("FASES_ULTIMA_PASTA_ID", ultimaLinhaProcessada.toString());
  sheet.getRange("A1").setValue("DATA ANÁLISE").setFontColor("#FFFFFF");

  try { if (typeof aplicarDesignProfissional === "function") aplicarDesignProfissional(true); } catch(e){}

  if (!modoSilencioso && processados > 0) {
      Browser.msgBox("✨ TERMÔMETROS CALIBRADOS", `Urgentes: ${urgentesProcessados} | Normais: ${processados - urgentesProcessados}`, Browser.Buttons.OK);
  }
}

