function calcularPrioridade(dadosLinha) {
  let fase = String(dadosLinha[17]); 
  let prazo = String(dadosLinha[7]); 
  let classe = String(dadosLinha[6]); 
  let leituraArvore = dadosLinha[16] instanceof Date ? dadosLinha[16] : new Date(0); 
  let ultimaVarredura = dadosLinha[9] instanceof Date ? dadosLinha[9] : new Date(0); 

  let is100 = fase.includes("100%");
  let isLEP = classe.toUpperCase().includes("EXECUÇÃO PENAL") || classe.toUpperCase().includes("LEP");

  if (is100 && !isLEP) return "PULAR"; 

  if (fase.includes("❌ Erro") || fase.includes("❌ IA:")) return 1; // Prioriza quem deu erro antes

  if (prazo.match(/\d{2}\/\d{2}\/\d{4}/)) {
      let p = prazo.match(/(\d{2})\/(\d{2})\/(\d{4})/);
      let d = new Date(p[3], parseInt(p[2])-1, p[1]);
      let hj = new Date(); hj.setHours(0,0,0,0);
      let dias = (d - hj) / (1000*60*60*24);
      if (dias >= 0 && dias <= 3) return 1;
      if (dias > 3 && dias <= 7) return 2;
  }

  if (fase === "" || fase.includes("⏳")) return 2;
  if (leituraArvore > ultimaVarredura) return 2; 

  let diasSemAtt = (Date.now() - ultimaVarredura) / (1000*60*60*24);
  if (diasSemAtt > 5) return 3;

  return "PULAR"; 
}

function montarContextoCliente(pastaCliente, dadosLinha) {
  let ctx = {
      textoArvore: "", textoDossie: "",
      classeProcessual: String(dadosLinha[6]), prazoFatal: String(dadosLinha[7]), 
      cnj: String(dadosLinha[8]), parteContraria: String(dadosLinha[11]), 
      resumoAtual: String(dadosLinha[12]), proximaAcao: String(dadosLinha[13]), 
      sistema: String(dadosLinha[14]), expedientes: String(dadosLinha[15]), 
      faseAtual: String(dadosLinha[17]), valorAtual: String(dadosLinha[18]), 
      areaDetectada: "CIVIL_GERAL"
  };

  function lerTextoRápido(arquivo) {
      try {
          if (arquivo.getMimeType() === MimeType.GOOGLE_DOCS) return DocumentApp.openById(arquivo.getId()).getBody().getText().substring(0, 4000);
      } catch(e) {} return "";
  }

  let arqs = pastaCliente.searchFiles("title contains 'ARVORE' or title contains 'MOVIMENTACAO' or title contains '[OCR]'");
  if (!arqs.hasNext()) {
      let g = pastaCliente.getFoldersByName("03_Andamentos_Despachos");
      if (g.hasNext()) arqs = g.next().searchFiles("title contains 'ARVORE' or title contains 'MOVIMENTACAO'");
  }
  if (arqs.hasNext()) ctx.textoArvore = lerTextoRápido(arqs.next());

  let dossies = pastaCliente.searchFiles("title contains 'DOSSIÊ VIVO'");
  if (dossies.hasNext()) ctx.textoDossie = lerTextoRápido(dossies.next());

  ctx.areaDetectada = detectarAreaPorTexto(ctx.textoArvore + ctx.textoDossie, ctx.classeProcessual);
  return ctx;
}

function detectarAreaPorTexto(texto, classe) {
  let g = classe.toUpperCase();
  if (g.includes("EXECUÇÃO PENAL") || g.includes("LEP")) return "EXECUCAO_PENAL";
  if (g.includes("HABEAS") || g.includes("CRIMINAL") || g.includes("PENAL")) return "CRIMINAL";
  if (g.includes("TRABALHISTA") || g.includes("TRT")) return "TRABALHISTA";
  if (g.includes("PREVIDENCIÁRIO") || g.includes("INSS")) return "PREVIDENCIARIO";
  if (g.includes("FAMÍLIA") || g.includes("DIVÓRCIO") || g.includes("ALIMENTOS")) return "FAMILIA";
  if (g.includes("CONSUMIDOR") || g.includes("BANCÁRIO")) return "CONSUMIDOR";
  return "CIVIL_GERAL";
}

function montarPromptFase(ctx, dataHoje) {
  let instrucaoEsp = "FASE deve ser do Procedimento Comum: Distribuição, Contestação, Réplica, Saneamento, Instrução, Sentença, Recurso, Execução.";
  if (ctx.areaDetectada === "EXECUCAO_PENAL") instrucaoEsp = "FASE deve ser o próximo benefício: Progressão, Saída Temp., Livramento. PERC = estimativa de pena cumprida. URGENCIA = CRITICA se PAD.";
  else if (ctx.areaDetectada === "CRIMINAL") instrucaoEsp = "FASE deve ser: Liminar Pendente, Aguardando PGJ, Julgamento, Recurso. URGENCIA = CRITICA se prazo manifestação urgente.";
  else if (ctx.areaDetectada === "TRABALHISTA") instrucaoEsp = "FASE deve ser: Audiência, Instrução, Sentença 1ª Inst., RO.";
  else if (ctx.areaDetectada === "FAMILIA") instrucaoEsp = "FASE deve ser: Citação, Contestação, Conciliação, Sentença. CRÍTICA se atraso alimentar.";

  return `Aja como Analista Jurídico Sênior do Dr. Lucas Semim. Hoje é ${dataHoje}. Área: ${ctx.areaDetectada}.

  CONTEXTO DA PLANILHA:
  Classe: ${ctx.classeProcessual}
