  DOCUMENTOS BASE:
  [ARVORE]\n${ctx.textoArvore}\n
  [DOSSIE]\n${ctx.textoDossie}\n

  INSTRUÇÕES:
  ${instrucaoEsp}
  MUDANCA_DETECTADA = 'SIM' se a fase mudou da atual (${ctx.faseAtual}).

  RESPONDA APENAS COM TAGS:
  [FASE]...[/FASE]
  [PERC]...[/PERC]
  [VALOR]...[/VALOR]
  [URGENCIA]...[/URGENCIA] (CRITICA, ALTA, NORMAL, BAIXA)
  [MUDANCA_DETECTADA]...[/MUDANCA_DETECTADA]`;
}

function construirBarraFase(fase, percNum, area, urgencia, prazoFatal) {
  let icone = "🏛️";
  if (area === "EXECUCAO_PENAL") icone = "🔒";
  else if (area === "CRIMINAL") icone = "⚖️";
  else if (area === "TRABALHISTA") icone = "👷";
  else if (area === "PREVIDENCIARIO") icone = "🏥";
  else if (area === "FAMILIA") icone = "👨‍👩‍👧";
  else if (area === "CONSUMIDOR") icone = "🛒";

  let blocos = Math.round(percNum / 10);
  let barraTexto = "[" + "█".repeat(blocos) + "░".repeat(10 - blocos) + "] " + percNum + "%";

  let prefixo = "";
  if (urgencia === "CRITICA") prefixo = "🚨 ";
  else if (urgencia === "ALTA") prefixo = "⚠️ ";
  else if (percNum === 100) prefixo = "⭐ ";

  let stringFinal = `${prefixo}${barraTexto}\n${icone} ${fase.toUpperCase()}`;

  if (prazoFatal.match(/\d{2}\/\d{2}\/\d{4}/) && (urgencia === "CRITICA" || urgencia === "ALTA")) {
      stringFinal += `\n⏰ Prazo: ${prazoFatal}`;
  }
  return stringFinal;
}

function deletarTriggersAntigos(nomeFuncao) {
  let triggers = ScriptApp.getProjectTriggers();
  for (let i = 0; i < triggers.length; i++) {
    if (triggers[i].getHandlerFunction() === nomeFuncao) ScriptApp.deleteTrigger(triggers[i]);
  }
}

