/**
 * 14 - DOUTRINADOR DE TESES V5.0 (MINERADOR ESTRATÉGICO)
 * Índice de Catálogo + Anti-Duplicata + Vinculação Automática
 * Anotação no Dossiê + Fôlego Infinito + Memória de Posição
 * Dr. Lucas Renan Semim - OAB/MG 222.539
 */

const MAX_IA_CALLS_TESES = 5;

function estudarCofreDeTeses(modoSilencioso = false) {
  const tempoInicio = Date.now();
  const limiteTempo = 270000; // 4.5 min

  const props = PropertiesService.getScriptProperties();

  // 1. Memória e Estado do Cofre
  let gavetaIdxMarcador = parseInt(props.getProperty("TESES_ULTIMA_GAVETA_IDX")) || 0;
  let processadosIds = [];
  try { processadosIds = JSON.parse(props.getProperty("TESES_PROCESSADOS_IDS")) || []; } catch(e) {}

  if (processadosIds.length > 300) processadosIds = processadosIds.slice(-150); // Limpeza de segurança

  let catalogo = obterCatalogoDeTeses();

  const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO);
  let pastasCofre = pastaRaiz.getFoldersByName("00_COFRE_DE_TESES_VENCEDORAS");

  if (!pastasCofre.hasNext()) {
      if (!modoSilencioso) Browser.msgBox("⚠️ ERRO", "Pasta do Cofre não encontrada.", Browser.Buttons.OK);
      return;
  }

  const cofre = pastasCofre.next();
  let gavetasParaOlhar = [cofre]; 
  let subpastas = cofre.getFolders();
  while(subpastas.hasNext()){
      gavetasParaOlhar.push(subpastas.next());
  }

  let chamadasIA = 0;
  let tesesMineradas = 0;
  let duplicatasEncontradas = 0;
  let clientesVinculados = 0;
  let erros = 0;

  // 2. Varredura do Cofre
  for (let g = gavetaIdxMarcador; g < gavetasParaOlhar.length; g++) {
      if (Date.now() - tempoInicio > limiteTempo) break;
      if (chamadasIA >= MAX_IA_CALLS_TESES) break;

      let gavetaAtual = gavetasParaOlhar[g];
      let arquivos = gavetaAtual.searchFiles("(mimeType = 'application/pdf' or mimeType = 'application/vnd.google-apps.document') and trashed = false");

      while (arquivos.hasNext()) {
          if (Date.now() - tempoInicio > limiteTempo) break;
          if (chamadasIA >= MAX_IA_CALLS_TESES) break;

          let arq = arquivos.next();
          let idArq = arq.getId();
          let nomeArq = arq.getName();
          let mimeType = arq.getMimeType();

          if (processadosIds.includes(idArq)) continue;
          if (nomeArq.match(/\[ESTUDADO\]|\[MINUTA PADRÃO\]|\[ERRO|\[DUPLICADO\]/i)) {
              if (!processadosIds.includes(idArq)) processadosIds.push(idArq);
              continue;
          }

          console.log(`[TESES] Analisando acórdão/tese: ${nomeArq}`);

          // a) EXTRAÇÃO DE TEXTO
          let textoExtraido = "";
          let docTempId = null;

          try {
              if (mimeType === MimeType.GOOGLE_DOCS) {
                  textoExtraido = DocumentApp.openById(idArq).getBody().getText().substring(0, 15000);
              } else if (mimeType === MimeType.PDF) {
                  try {
                      let arquivoTemp = { title: "Temp_Leitura_IA_" + idArq, mimeType: MimeType.GOOGLE_DOCS };
                      let docTemp = Drive.Files.copy(arquivoTemp, idArq, {ocr: true, ocrLanguage: 'pt-BR'}); 
                      docTempId = docTemp.id;
                      textoExtraido = DocumentApp.openById(docTempId).getBody().getText().substring(0, 15000); 
                  } finally {
                      if (docTempId) Drive.Files.remove(docTempId); // REGRA 5: Lixeiro Digital Absoluto
                  }
              }

              if (textoExtraido.trim().length < 50) {
                  arq.setName("[ERRO LEITURA] " + nomeArq); 
                  processadosIds.push(idArq);
                  erros++;
                  continue;
              }

              // b) VERIFICAÇÃO DE DUPLICIDADE
              let dupCheck = verificarDuplicidade(textoExtraido, catalogo);
              if (dupCheck.duplicada) {
                  arq.setName(`[DUPLICADO][ESTUDADO] ${nomeArq}`);
                  processadosIds.push(idArq);
                  duplicatasEncontradas++;
                  console.log(`[TESES] Duplicata detectada: similaridade de ${dupCheck.similaridade.toFixed(1)}% com ${dupCheck.teseExistente.nome}`);
                  continue;
              }

              // c) CHAMADA À IA
              let prompt = montarPromptDoutrinador(textoExtraido, nomeArq);
              let respostaIA = CHAMAR_IA_ESCRITORIO(prompt, "PRO");
              chamadasIA++;
              Utilities.sleep(5000); // REGRA 4: Cota de IA e Sleep OBRIGATÓRIO

              if (respostaIA.includes("❌")) {
                  let erroReal = respostaIA.replace("❌", "").trim().substring(0, 40);
                  arq.setName(`[ERRO IA: ${erroReal}] ${nomeArq}`);
                  console.log(`[TESES] ❌ Erro real da IA: ${respostaIA}`);
                  erros++;
                  continue; // REGRA 3: Expor erro sem mascarar
              }

              // d) EXTRAÇÃO DAS TAGS
              let teseExtraida = {
                  area: extrairTagTese(respostaIA, "AREA_DIREITO") || "CIVIL_GERAL",
                  tema_resumido: extrairTagTese(respostaIA, "TEMA_RESUMIDO") || nomeArq.replace(".pdf", ""),
                  tribunal: extrairTagTese(respostaIA, "TRIBUNAL_ORIGEM") || "Não identificado",
                  data_julgado: extrairTagTese(respostaIA, "DATA_JULGADO") || "",
                  num_origem: extrairTagTese(respostaIA, "NUMERO_PROCESSO_ORIGEM") || "Não identificado",
                  sumulas: extrairTagTese(respostaIA, "SUMULAS_E_ARTIGOS") || "Não extraído",
                  fundamentacao: extrairTagTese(respostaIA, "FUNDAMENTACAO_PRINCIPAL") || "Não extraído",
                  gatilhos: extrairTagTese(respostaIA, "GATILHOS_DE_APLICACAO") || "Não extraído",
                  keywordsStr: extrairTagTese(respostaIA, "KEYWORDS_BUSCA") || "",
                  tipo_peticao: extrairTagTese(respostaIA, "TIPO_PETICAO_IDEAL") || "TODAS",
                  alerta: extrairTagTese(respostaIA, "ALERTA_ATUALIZACAO") || "",
                  minuta: extrairTagTese(respostaIA, "MINUTA_BASE") || "Erro na geração da minuta.",
                  beneficiados: extrairTagTese(respostaIA, "PROCESSOS_BENEFICIADOS") || "",
                  hash_conteudo: textoExtraido.substring(0, 100)
              };

              teseExtraida.keywords = teseExtraida.keywordsStr.split("|").map(k => k.trim().toLowerCase());

              // e) VERIFICAÇÃO DE ATUALIDADE
              let atualidade = verificarAtualidade(teseExtraida.data_julgado);
              if (atualidade.atual === false) {
                  teseExtraida.alerta = `⚠️ ${atualidade.aviso} ` + teseExtraida.alerta;
              }

              // f) CRIAÇÃO DO DOCUMENTO MINUTA
              let nomeMinuta = `[MINUTA PADRÃO] - ${nomeArq.replace(".pdf", "")}`;
              criarDocumentoMinuta(teseExtraida, nomeMinuta, gavetaAtual);
              arq.setName(`[ESTUDADO] ${nomeArq}`);

              // g) ATUALIZAÇÃO DO ÍNDICE
              teseExtraida.id = idArq;
              teseExtraida.nome = nomeMinuta;
              atualizarIndiceCofre(teseExtraida, catalogo, props);
              processadosIds.push(idArq);
              tesesMineradas++;

              // h) VINCULAÇÃO COM PROCESSOS ATIVOS (Sem Custo de IA)
              let vinculados = vincularTeseAosClientes(teseExtraida, nomeMinuta);
              clientesVinculados += vinculados;

              // i) SALVAR MARCADOR IMEDIATO
              props.setProperty("TESES_ULTIMA_GAVETA_IDX", g.toString());

          } catch(e) {
              console.log(`[TESES] Erro fatal no arquivo ${nomeArq}: ${e.message}`);
              arq.setName(`[ERRO SISTEMA] ${nomeArq}`);
              processadosIds.push(idArq);
              erros++;
          }
      }
  }

  // 4. Salvar estado final
  props.setProperty("TESES_PROCESSADOS_IDS", JSON.stringify(processadosIds));

  if (chamadasIA < MAX_IA_CALLS_TESES) {
      // Terminou todas as gavetas
      props.deleteProperty("TESES_ULTIMA_GAVETA_IDX");
      console.log("[TESES] Ciclo completo. O cofre inteiro foi varrido.");
  }

  console.log(`[TESES] Rodada: ${tesesMineradas} teses | ${duplicatasEncontradas} duplicatas | ${clientesVinculados} vinculações | ${erros} erros.`);

  if (!modoSilencioso && (tesesMineradas > 0 || erros > 0 || duplicatasEncontradas > 0)) {
      Browser.msgBox("✅ DOUTRINADOR V5.0", 
          `Análise Estratégica Concluída!\n\n` +
          `📜 Novas Minutas Geradas: ${tesesMineradas}\n` +
          `🎯 Clientes Vinculados Auto: ${clientesVinculados}\n` +
          `🔄 Duplicatas Evitadas: ${duplicatasEncontradas}\n` +
          `❌ Erros/Ilegíveis: ${erros}\n` +
          `🤖 Chamadas IA: ${chamadasIA}/${MAX_IA_CALLS_TESES}`, 
          Browser.Buttons.OK);
  } else if (!modoSilencioso) {
      Browser.msgBox("ℹ️ AVISO", "Nenhum acórdão novo pendente no Cofre.", Browser.Buttons.OK);
  }
}

