// 📚 CATÁLOGO E INTELIGÊNCIA DE DUPLICIDADE
// =========================================================================
function obterCatalogoDeTeses() {
    const props = PropertiesService.getScriptProperties();
    let cat = props.getProperty("TESES_INDICE_CATALOGO");
    if (cat) {
        try { return JSON.parse(cat); } catch(e) {}
    }
    return { ultima_atualizacao: "", total_teses: 0, por_area: {}, teses: [] };
}

function atualizarIndiceCofre(tese, catalogo, props) {
    catalogo.teses.push(tese);
    catalogo.total_teses++;
    catalogo.por_area[tese.area] = (catalogo.por_area[tese.area] || 0) + 1;
    catalogo.ultima_atualizacao = Utilities.formatDate(new Date(), "GMT-3", "dd/MM/yyyy HH:mm");
    props.setProperty("TESES_INDICE_CATALOGO", JSON.stringify(catalogo));
}

function verificarDuplicidade(textoNovo, catalogo) {
    if (!catalogo.teses || catalogo.teses.length === 0) return { duplicada: false, similaridade: 0 };

    // Simplificação radical: pega palavras > 5 chars
    let palavrasNovo = textoNovo.toLowerCase().match(/\b[a-zà-ú]{6,}\b/g) || [];
    let setNovo = new Set(palavrasNovo);

    let melhorSimilaridade = 0;
    let teseSimilar = null;

    for (let tese of catalogo.teses) {
        if (!tese.keywords || tese.keywords.length === 0) continue;

        let matchCount = 0;
        for (let kw of tese.keywords) {
            if (kw.length > 3 && textoNovo.toLowerCase().includes(kw)) matchCount++;
        }

        let sim = (matchCount / tese.keywords.length) * 100;
        if (sim > melhorSimilaridade) {
            melhorSimilaridade = sim;
            teseSimilar = tese;
        }
    }

    return { duplicada: (melhorSimilaridade >= 70), teseExistente: teseSimilar, similaridade: melhorSimilaridade };
}

function verificarAtualidade(dataJulgado) {
    if (!dataJulgado || dataJulgado.trim() === "") return { atual: null };

    let match = dataJulgado.match(/(\d{2})\/(\d{2})\/(\d{4})/);
    if (!match) match = dataJulgado.match(/(\d{4})/); // Tenta achar só o ano

    if (match) {
        let ano = match.length === 4 ? parseInt(match[3]) : parseInt(match[1]);
        let anoAtual = new Date().getFullYear();
        if ((anoAtual - ano) >= 3) {
            return { atual: false, aviso: `Tese datada de ${ano}. Atenção: Verifique se o entendimento do tribunal não foi superado nos últimos anos.` };
        }
        return { atual: true };
    }
    return { atual: null };
}

// =========================================================================
// 🎯 VINCULAÇÃO E ANOTAÇÃO (GEOGRAFIA E SINFONIA)
// =========================================================================
function vincularTeseAosClientes(teseExtraida, nomeDocMinuta) {
    let vinculados = 0;
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    let sheet = ss.getSheetByName("Dashboard Principal") || ss.getSheetByName("PROCESSOS");
    if (!sheet) return 0;

    let dados = sheet.getDataRange().getValues();
    let matches = [];

    // REGRA 2: Geografia (For começando de i=2 = Linha 3)
    for (let i = 2; i < dados.length; i++) {
        let nome = String(dados[i][1]); // Col B
        let urlPasta = String(dados[i][4]); // Col E
        let classe = String(dados[i][6]).toLowerCase(); // Col G
        let resumo = String(dados[i][12]).toLowerCase(); // Col M
        let proxAcao = String(dados[i][13]).toLowerCase(); // Col N
        let teseAtual = String(dados[i][19]).trim(); // Col T

        if (!nome.includes("CLIENTE:") || urlPasta === "") continue;
        if (teseAtual !== "" && !teseAtual.includes("⏳")) continue; // Já tem tese forte

        let contextoProcesso = `${classe} ${resumo} ${proxAcao}`;
        let matchCount = 0;

        for (let kw of teseExtraida.keywords) {
            if (kw.length > 3 && contextoProcesso.includes(kw)) matchCount++;
        }

        if (matchCount >= 3) {
            matches.push({ linha: i + 1, matchCount: matchCount, url: urlPasta });
        }
    }

    // Pega os 3 melhores matches para não floodar
    matches.sort((a, b) => b.matchCount - a.matchCount);
    let selecionados = matches.slice(0, 3);

    for (let sel of selecionados) {
        // ZERO FÓRMULAS: Apenas texto estático
        sheet.getRange(sel.linha, 20).setValue(`⚖️ ${teseExtraida.tema_resumido} (Auto-vinculada)`);
        anotarTeseNoDossie(sel.url, teseExtraida, nomeDocMinuta);
        vinculados++;
        console.log(`[TESES] Tese vinculada ao processo na linha ${sel.linha}`);
    }

    return vinculados;
}

function anotarTeseNoDossie(urlPastaCliente, teseExtraida, nomeDocMinuta) {
    try {
        let idPasta = urlPastaCliente.split("folders/")[1]?.split("?")[0];
        if (!idPasta) return;

        let pastaCliente = DriveApp.getFolderById(idPasta);
        let files = pastaCliente.searchFiles("title contains 'DOSSIÊ VIVO' or title contains 'DOSSIE'");

        if (files.hasNext()) {
            let fileDossie = files.next();
            if (fileDossie.getMimeType() === MimeType.GOOGLE_DOCS) {
                let doc = DocumentApp.openById(fileDossie.getId());
                let body = doc.getBody();

                let adendo = `\n========================================\n` +
                             `⚖️ TESES JURÍDICAS APLICÁVEIS\n` +
                             `${Utilities.formatDate(new Date(), "GMT-3", "dd/MM/yyyy")} — Tese Vinculada Automaticamente:\n` +
                             `📌 Tema: ${teseExtraida.tema_resumido}\n` +
                             `📖 Fundamento: ${teseExtraida.sumulas}\n` +
                             `📂 Arquivo: ${nomeDocMinuta}\n` +
                             `🎯 Aplicar em: ${teseExtraida.tipo_peticao}\n` +
                             `----------------------------------------\n`;

                body.appendParagraph(adendo);
                doc.saveAndClose();
            }
        }
    } catch(e) {
        console.log(`[TESES] Erro ao anotar no dossiê: ${e.message}`);
    }
}

