function extrairTagTese(texto, tag) {
    let m = texto.match(new RegExp("\\[" + tag + "\\]([\\s\\S]*?)(?:\\[\\/" + tag + "\\])", "i"));
    return m ? m[1].replace(/^\*\*|\*\*$/g, "").trim() : "";
}

function reconstruirIndiceCofre(modoSilencioso = false) {
    const props = PropertiesService.getScriptProperties();
    props.deleteProperty("TESES_INDICE_CATALOGO");
    let catalogo = { ultima_atualizacao: "", total_teses: 0, por_area: {}, teses: [] };

    const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO);
    let pastasCofre = pastaRaiz.getFoldersByName("00_COFRE_DE_TESES_VENCEDORAS");
    if (!pastasCofre.hasNext()) return;

    let arquivos = pastasCofre.next().searchFiles("title contains '[MINUTA PADRÃO]' and trashed = false");

    while(arquivos.hasNext()) {
        let arq = arquivos.next();
        try {
            let txt = DocumentApp.openById(arq.getId()).getBody().getText().substring(0, 1000);
            let area = txt.match(/([A-Z_]+)\s*\|\s*[A-Z]+/) ? txt.match(/([A-Z_]+)\s*\|\s*[A-Z]+/)[1] : "CIVIL_GERAL";

            let tese = {
                id: arq.getId(), nome: arq.getName(), area: area,
                tema: arq.getName().replace("[MINUTA PADRÃO] -", "").trim(),
                keywords: [], tribunal: "Não identificado", data_julgado: "",
                hash_conteudo: txt.substring(0, 100)
            };
            atualizarIndiceCofre(tese, catalogo, props);
        } catch(e) {}
    }
    console.log(`[TESES] Catálogo reconstruído: ${catalogo.total_teses} teses.`);
    if (!modoSilencioso) Browser.msgBox("🔄 RECONSTRUÇÃO", "Índice do Cofre recriado com sucesso!", Browser.Buttons.OK);
}

function deletarTriggersAntigos(nomeFuncao) {
  let triggers = ScriptApp.getProjectTriggers();
  for (let i = 0; i < triggers.length; i++) {
    if (triggers[i].getHandlerFunction() === nomeFuncao) ScriptApp.deleteTrigger(triggers[i]);
  }
}

