    const cpf = dados.cpf || "Não informado";
    const numProcesso = dados.numProcesso || "";
    const relato = dados.relato || "Sem relato detalhado.";
    const situacao = dados.situacao || "Não especificada";
    const arquivosBase64 = dados.arquivos || []; 

    // O ID_RAIZ_ESCRITORIO deve estar definido como variável global no topo do seu projeto
    const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO);
    let pasta01 = pastaRaiz.getFoldersByName("01_CLIENTES");
    let pastaClientes = pasta01.hasNext() ? pasta01.next() : pastaRaiz;

    // 2. CRIAÇÃO DA PASTA DO CLIENTE
    let nomePasta = nomeCliente;
    if (numProcesso && numProcesso.length > 5) {
        nomePasta += " - Proc: " + numProcesso;
    }
    const novaPastaCliente = pastaClientes.createFolder(nomePasta);

    // 3. GAVETAS PADRÃO DO ESCRITÓRIO
    const gavetaDocs = novaPastaCliente.createFolder("01_Docs_Pessoais");
    const gavetaProvas = novaPastaCliente.createFolder("02_Provas");
    const gavetaAndamentos = novaPastaCliente.createFolder("03_Andamentos_Despachos");

    // 4. DESEMPACOTAMENTO E TRIAGEM INTELIGENTE DE ARQUIVOS BASE64
    if (arquivosBase64.length > 0) {
        arquivosBase64.forEach(arq => {
            let blob = Utilities.newBlob(Utilities.base64Decode(arq.data), arq.mimeType, arq.nome);

            // Triagem: Identifica se é documento pessoal ou prova geral pelo nome
            let nomeArqLimpo = String(arq.nome).toLowerCase();
            if (nomeArqLimpo.match(/(rg|cpf|cnh|identidade|documento|comprovante|endereco)/)) {
               gavetaDocs.createFile(blob);
            } else {
               gavetaProvas.createFile(blob);
            }
        });
    }

    // 5. CRIAÇÃO DO DOSSIÊ VIVO INICIAL
    const ID_TIMBRADO = "1gpj_AFkHwRWxggGcmr-mYBVKQw9QyuVy";

    // makeCopy já coloca o arquivo na gavetaAndamentos, sem precisar de moveTo extra
    const novoArquivo = DriveApp.getFileById(ID_TIMBRADO).makeCopy("DOSSIÊ VIVO - " + nomeCliente, gavetaAndamentos);

    const docDossie = DocumentApp.openById(novoArquivo.getId());
    const body = docDossie.getBody();

    body.appendParagraph("📋 DOSSIÊ VIVO - " + nomeCliente).setHeading(DocumentApp.ParagraphHeading.HEADING1);
    body.appendParagraph("Gerado automaticamente via API nativa do site lucassemim.adv.br\n");

    body.appendParagraph("DADOS DO CLIENTE").setHeading(DocumentApp.ParagraphHeading.HEADING2);
    body.appendParagraph("Nome: " + nomeCliente);
    body.appendParagraph("E-mail: " + emailCliente); // 🔥 NOVO: Registro do e-mail
    body.appendParagraph("WhatsApp: " + whatsapp);
    body.appendParagraph("CPF: " + cpf);
    body.appendParagraph("Situação: " + situacao);
    if (numProcesso) body.appendParagraph("Processo CNJ: " + numProcesso);

    body.appendParagraph("\nRELATO DOS FATOS").setHeading(DocumentApp.ParagraphHeading.HEADING2);
    body.appendParagraph(relato);

    docDossie.saveAndClose();

    // 6. RESPOSTA PARA O SITE
    return ContentService.createTextOutput(JSON.stringify({
      "status": "sucesso", 
      "mensagem": "Pasta e Dossiê criados com sucesso!"
    })).setMimeType(ContentService.MimeType.JSON);

  } catch (erro) {
     return ContentService.createTextOutput(JSON.stringify({
       "status": "erro", 
       "mensagem": erro.message
     })).setMimeType(ContentService.MimeType.JSON);
  }
}

