  }

  let pastaEsteiraFb = pastasEsteira.next();
  let pastasMae = pastaEsteiraFb.getFoldersByName("00_PROCESSOS_MAE");
  let pastasClientes = pastaEsteiraFb.getFoldersByName("01_CLIENTES_EXECUCAO");

  if (!pastasMae.hasNext() || !pastasClientes.hasNext()) {
