  let arquivosStatus = pastaMae.searchFiles("title contains '[STATUS]'");
  let statusGeral = "⏳ SUSPENSO - AGUARDANDO TRIBUNAL"; // Padrão de segurança
  let orientacaoEstrategica = "O processo principal encontra-se suspenso.";

  if (arquivosStatus.hasNext()) {
      let docStatus = arquivosStatus.next();
      if (docStatus.getMimeType() === MimeType.GOOGLE_DOCS) {
         orientacaoEstrategica = DocumentApp.openById(docStatus.getId()).getBody().getText().substring(0, 3000); 

         // O robô analisa as palavras-chave para definir o status da linha de produção!
         if (orientacaoEstrategica.toLowerCase().includes("liberado") || orientacaoEstrategica.toLowerCase().includes("procedente")) {
             statusGeral = "🟢 PRONTO PARA PROTOCOLO (LIBERADO)";
         }
      }
  }

  // 3. VARREDURA DOS CLIENTES E CRIAÇÃO EM MASSA
  let clientes = pastaCli.getFolders();
  let dadosAba = abaEsteira.getDataRange().getValues();
  let contLidos = 0;
  let minutasGeradas = 0;

  while (clientes.hasNext() && contLidos < 5) { // Trava de Segurança (Limites de Tempo)
      let cliente = clientes.next();
      let nomeCliente = cliente.getName();
      let urlCliente = cliente.getUrl();

      if (nomeCliente.includes("00_") || nomeCliente.includes("MODELO")) continue;

      // Procura o cliente na aba da Esteira Facebook
      let linhaEncontrada = -1;
      let statusMinutaAtual = "";

      for (let i = 1; i < dadosAba.length; i++) { // Começa do 1 para pular o cabeçalho
         if (String(dadosAba[i][1]).trim() === nomeCliente.trim()) { // Coluna B (Index 1) = NOME
            linhaEncontrada = i + 1;
            statusMinutaAtual = String(dadosAba[i][7]); // 🔥 AJUSTE: Coluna H (Index 7) = STATUS MINUTA
            break;
         }
      }

      // Se o cliente é novo (Não estava na planilha), cria a linha com as 9 COLUNAS
      if (linhaEncontrada === -1) {
         let dataHoje = Utilities.formatDate(new Date(), "GMT-3", "dd/MM/yyyy");
         // Ordem Exata: A(Data) | B(Cliente) | C(Email) | D(URL Pasta) | E(Status Docs) | F(URL Perfil) | G(Valor) | H(Status Minuta) | I(Protocolo)
         abaEsteira.appendRow([
             dataHoje,            // A: DATA
             nomeCliente,         // B: CLIENTE / PASTA
             "Não Informado",     // C: E-MAIL
             urlCliente,          // D: URL PASTA
             "Falta Doc",         // E: STATUS DOCS
             "Pendente Link",     // F: URL DO PERFIL
             "R$ 0,00",           // G: VALOR
             "⏳ Pendente Geração", // H: STATUS MINUTA
             "Aguardando"         // I: PROTOCOLO
         ]);
         linhaEncontrada = abaEsteira.getLastRow();
         statusMinutaAtual = "⏳ Pendente Geração";
      }

      // 4. O GATILHO DA INTELIGÊNCIA ARTIFICIAL
      // Gera minuta SE não houver OU SE o status Global (Doc Mãe) mudou, mas PULA se já foi protocolado.
      if (statusMinutaAtual !== statusGeral && !statusMinutaAtual.includes("✅ PROTOCOLADO")) {

         abaEsteira.getRange(linhaEncontrada, 8).setValue("⏳ IA Redigindo..."); // Escreve na Coluna H
         SpreadsheetApp.flush();

         // Puxa os fatos do cliente (se houver um Dossiê preenchido na pasta dele)
         let fatosCliente = "Cliente titular de conta na plataforma Facebook/Instagram, afetado por falha na prestação do serviço e vazamento/bloqueio indevido.";
         let arquivosDossie = cliente.searchFiles("title contains 'DOSSIÊ'");
         if (arquivosDossie.hasNext()) {
             let docDossie = arquivosDossie.next();
             if (docDossie.getMimeType() === MimeType.GOOGLE_DOCS) {
                fatosCliente = DocumentApp.openById(docDossie.getId()).getBody().getText().substring(0, 2000);
             }
         }

         // 🧠 PROMPT ESTRATÉGICO CÍVEL (Ajustado para a rede civel.lucassemim.adv.br)
         let prompt = `Você é um Advogado Sênior Especialista em Direito Digital e Responsabilidade Civil do escritório Lucas Semim Advogados (OAB/MG: 222.539).

         CENÁRIO JURÍDICO ATUAL DA AÇÃO CIVIL PÚBLICA:
         "${orientacaoEstrategica}"

         FATOS DO CLIENTE (TITULAR DA CONTA):
         "${fatosCliente}"

         MISSÃO:
         Redija a Peça de Cumprimento Individual de Sentença (ou Habilitação) contra o Facebook Serviços Online do Brasil Ltda (Meta Platforms).

         DIRETRIZES CÍVEIS OBRIGATÓRIAS:
         1. Adeque o tom rigorosamente ao CENÁRIO JURÍDICO. Se o documento mãe diz "suspenso", peça apenas habilitação/reserva de crédito. Se diz "liberado", peça penhora imediata via SISBAJUD (Teoria do Risco do Empreendimento e Súmula 479 STJ).
         2. Invoque os artigos 6º e 14 do Código de Defesa do Consumidor (Responsabilidade Objetiva).
         3. Não invente valores financeiros. Use o marcador [R$ INSERIR_VALOR_AQUI].
         4. Entregue APENAS a peça jurídica formatada, pronta para uso, sem introduções amigáveis. Inicie com "EXCELENTÍSSIMO SENHOR JUIZ DE DIREITO...".`;

         // Usamos FLASH para velocidade em escala de produção
         let pecaGerada = CHAMAR_IA_ESCRITORIO(prompt, "FLASH"); 

         if (!pecaGerada.includes("❌") && !pecaGerada.includes("Erro")) {
             // Cria o documento injetando o Status no título para facilitar a revisão visual
             let dataAtual = Utilities.formatDate(new Date(), "GMT-3", "dd/MM");
             let nomeDoc = "[MINUTA " + dataAtual + "] Cumprimento Facebook - " + nomeCliente;

             let docMinuta = DocumentApp.create(nomeDoc);
             docMinuta.getBody().setText("⚠️ STATUS ESTRATÉGICO DA TESE: " + statusGeral + "\n\n" + pecaGerada);

             // Move o arquivo criado para a pasta correta
             DriveApp.getFileById(docMinuta.getId()).moveTo(cliente);

             // Carimba a Planilha de volta na Coluna H (8)
             abaEsteira.getRange(linhaEncontrada, 8).setValue(statusGeral);
             minutasGeradas++;
         } else {
             abaEsteira.getRange(linhaEncontrada, 8).setValue("❌ Erro na Geração");
         }
      }
      contLidos++;
  }

  if (minutasGeradas > 0) {
      Browser.msgBox("🚜 TRATOR DE EXECUÇÕES", minutasGeradas + " minutas de Cumprimento de Sentença (Meta/Facebook) foram geradas ou atualizadas com base no Processo Mãe!", Browser.Buttons.OK);
  } else {
      Browser.msgBox("🚜 TRATOR DE EXECUÇÕES", "A esteira rodou. Não há minutas novas para gerar nesta rodada ou os limites foram atingidos.", Browser.Buttons.OK);
  }
}

/**
 * 16 - ESTRATEGISTA JURÍDICO V4.5 (INTEGRAÇÃO TOTAL + SINERGIA DOSSIÊ)
 * V4.5: Sincronizado com Dashboard Master de 20 Colunas (A-T).
 * Lê URL(E), Resumo(M), Fase(R) e Escreve Tese na Coluna T (20).
 */

function sugerirTesesParaClientes() {
  const tempoInicio = Date.now(); 
  const limiteTempo = 280000; // 4.6 minutos

  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getActiveSheet();

  if (sheet.getName() !== "Dashboard Principal" && sheet.getName() !== "PROCESSOS") {
      Browser.msgBox("⚠️ ALERTA", "Diretor, o Estrategista roda apenas na aba do Dashboard Principal!", Browser.Buttons.OK);
      return;
  }

  console.log("Sincronizando Banco de Teses...");
  try {
      estudarCofreDeTeses(); // Mantém a função de aprendizado
      Utilities.sleep(1500); 
  } catch(e) { console.log("Erro ao sincronizar teses: " + e.message); }

  sheet.getRange("A1").setValue("⏳ Estrategista cruzando Inteligência 360º...").setFontColor("#9B59B6");

  const dados = sheet.getDataRange().getValues();
  const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO); // Usa a global

  // Localiza o cofre de teses
  const buscaCofre = pastaRaiz.getFoldersByName("00_COFRE_DE_TESES_VENCEDORAS");
  if (!buscaCofre.hasNext()) {
    sheet.getRange("A1").setValue("DATA ANÁLISE").setFontColor("#FFFFFF");
    Browser.msgBox("❌ ERRO", "Pasta '00_COFRE_DE_TESES_VENCEDORAS' não encontrada na raiz.", Browser.Buttons.OK);
    return;
  }
  const cofre = buscaCofre.next();

  // 1. CONSTRUIR CATÁLOGO DE TESES (Incluso subpastas)
  let catalogoTeses = "";
  let pastasParaVarrer = [cofre];
  let subsCofre = cofre.getFolders();
  while(subsCofre.hasNext()) pastasParaVarrer.push(subsCofre.next());

  pastasParaVarrer.forEach(pasta => {
    let minutas = pasta.searchFiles("title contains '[MINUTA PADRÃO]'");
    while(minutas.hasNext()){
      let m = minutas.next();
      try {
        let conteudo = DocumentApp.openById(m.getId()).getBody().getText().substring(0, 1200);
        catalogoTeses += `TESE: ${m.getName()}\nCONTEXTO JURÍDICO: ${conteudo}\n\n`;
      } catch(e) { console.log("Erro ao ler tese: " + m.getName()); }
    }
  });

  if (catalogoTeses === "") {
    sheet.getRange("A1").setValue("DATA ANÁLISE").setFontColor("#FFFFFF");
    Browser.msgBox("⚠️ AVISO", "Nenhuma '[MINUTA PADRÃO]' encontrada no Cofre de Teses.", Browser.Buttons.OK);
    return;
  }

  let aplicacoes = 0;
  let clientesAnalisadosNestaRodada = 0;

  // 2. VARREDURA COM SINERGIA DE DADOS (Sincronizado V3.8)
  for (let i = 1; i < dados.length; i++) {

    if (Date.now() - tempoInicio > limiteTempo) break;
    if (clientesAnalisadosNestaRodada >= 5) break; // Limite de chamadas IA por lote

    let nomeClienteFull = String(dados[i][1]); // Coluna B
    let urlPasta = String(dados[i][4]); // 🔥 Coluna E (Index 4)
    let resumoPlanilha = String(dados[i][12]); // 🔥 Coluna M (Index 12)
    let faseProcessual = String(dados[i][17]); // 🔥 Coluna R (Index 17)
    let teseAtual = String(dados[i][19]); // 🔥 Coluna T (Index 19)

    // 🧠 SÓ TRABALHA SE: Tiver cliente e a tese estiver vazia ou pendente
    if (nomeClienteFull && nomeClienteFull.includes("CLIENTE:") && (!teseAtual || teseAtual.includes("⏳") || teseAtual.includes("Aguardando") || teseAtual.trim() === "")) {

      let nomeBusca = nomeClienteFull.replace("CLIENTE: ", "").split(" - Proc:")[0].trim();
      let contextoParaIA = `Resumo da Planilha: ${resumoPlanilha}\nFase Processual Atual: ${faseProcessual}`;

      sheet.getRange(i + 1, 20).setValue("⏳ Procurando Tese..."); // Escreve na T
      SpreadsheetApp.flush();

      // 🔍 SINERGIA PROFUNDA: Tenta ler o DOSSIÊ VIVO primeiro
      try {
        if (urlPasta && urlPasta.includes("folders/")) {
            let idPasta = urlPasta.split("folders/")[1].split("?")[0];
            let pastaCli = DriveApp.getFolderById(idPasta);
            let arquivos = pastaCli.getFiles();

            while(arquivos.hasNext()) {
              let arq = arquivos.next();
              let nArq = arq.getName().toUpperCase();
              if (nArq.includes("DOSSIÊ VIVO") || nArq.includes("PETIÇÃO") || nArq.includes("INICIAL")) {
                let doc = DocumentApp.openById(arq.getId());
                let textoExtra = doc.getBody().getText().substring(0, 4000);
                contextoParaIA = `[DADOS PROFUNDOS DO PROCESSO]:\n${textoExtra}\n\nFase Atual: ${faseProcessual}`;
                break; 
              }
            }
        }
      } catch(e) { console.log("Contexto profundo não disponível para: " + nomeBusca); }

      let prompt = `ATUE COMO O ESTRATEGISTA JURÍDICO SÊNIOR DO ESCRITÓRIO DR. LUCAS SEMIM.
      Sua missão é realizar o MATCH perfeito entre os fatos do cliente e nossas teses vencedoras.

      CONTEXTO DO PROCESSO:
      "${contextoParaIA}"

      NOSSO COFRE DE TESES (CATÁLOGO):
      "${catalogoTeses}"

      REGRAS DE OURO:
      1. Se a fase for "Execução Penal", priorize teses de Remição, Progressão ou PAD.
      2. Se a matéria for Cível, busque teses de Indenização, Consumidor ou Bancário.
      3. Seja cirúrgico: Se houver match, responda no formato: [NOME DA TESE] + (Breve justificativa técnica de 1 frase).

      Exemplo: "Tese Revisional Bancária - Aplicável pela abusividade nos juros de mora detectados no dossiê."

      Se NENHUMA tese do catálogo se aplicar perfeitamente aos fatos do processo, responda apenas a palavra: NENHUMA.`;

      // Chama a IA 
      let sugestao = CHAMAR_IA_ESCRITORIO(prompt, "FLASH");

      if (sugestao && !sugestao.includes("NENHUMA") && !sugestao.includes("Erro") && !sugestao.includes("❌")) {
        // Limpa a resposta e aplica o emoji de balança
        let teseLimpa = sugestao.replace(/\*\*|\[|\]/g, "").trim();
        sheet.getRange(i + 1, 20).setValue("⚖️ " + teseLimpa); // Escreve na Coluna T (20)
        aplicacoes++;
      } else if (sugestao.includes("Erro") || sugestao.includes("❌")) {
        sheet.getRange(i + 1, 20).setValue("❌ Erro IA. Tente mais tarde.");
      } else {
        sheet.getRange(i + 1, 20).setValue("⏳ Aguardando tese compatível no Cofre...");
      }

      SpreadsheetApp.flush(); 
      clientesAnalisadosNestaRodada++;
    }
  }

  sheet.getRange("A1").setValue("DATA ANÁLISE").setFontColor("#FFFFFF");

  if (aplicacoes > 0) {
    Browser.msgBox("🎯 ESTRATEGISTA CONCLUÍDO", aplicacoes + " processos foram blindados com teses do cofre!", Browser.Buttons.OK);
  } else {
    Browser.msgBox("✅ TUDO PRONTO", "A varredura foi finalizada sem novos matches (Nenhuma tese nova aplicada nesta rodada).", Browser.Buttons.OK);
  }
}

/**
 * 18 - CARTEIRO DIGITAL V1.6 (CROSS-DATA CIRÚRGICO & REDE CÍVEL)
