  if (!sheetEmail || !sheetProcessos) {
      console.log("Erro: Abas necessárias não encontradas.");
      return;
  }

  const limiteDisparosPorRodada = 10; 
  let disparosRealizados = 0;

  const dadosEmail = sheetEmail.getDataRange().getValues();
  const dadosProcessos = sheetProcessos.getDataRange().getValues();

  // ⚠️ ATENÇÃO: O robô V1.6 pega o assunto e texto da LINHA 2 (índice 1)
  const assuntoGlobal = String(dadosEmail[1][2]).trim(); // Célula C2
  const corpoGlobal = String(dadosEmail[1][3]).trim();   // Célula D2

  if (!assuntoGlobal || !corpoGlobal) {
      Browser.msgBox("❌ ERRO", "O modelo do e-mail deve estar nas células C2 (Assunto) e D2 (Corpo).", Browser.Buttons.OK);
      return;
  }

  const emailRemetente = "doutorbrnews@gmail.com"; 
  const aliases = GmailApp.getAliases();
  const usarAlias = aliases.includes(emailRemetente) ? emailRemetente : null;

  sheetEmail.getRange("E1").setValue("⏳ Cruzando Dados e Disparando...").setFontColor("#D4AF37");
  SpreadsheetApp.flush();

  // =========================================================================
  // 🧹 1. O FAXINEIRO: LIMPEZA DE HARD BOUNCES
  // =========================================================================
  try {
     let threadsDeErro = GmailApp.search("is:unread from:(mailer-daemon@googlemail.com OR postmaster)");
     for (let t = 0; t < threadsDeErro.length; t++) {
        let mensagens = threadsDeErro[t].getMessages();
        for (let m = 0; m < mensagens.length; m++) {
           let textoErro = mensagens[m].getPlainBody();
           let regexEmail = /([a-zA-Z0-9._-]+@[a-zA-Z0-9._-]+\.[a-zA-Z0-9_-]+)/;
           let match = textoErro.match(regexEmail);
           if (match && match[1]) {
               let emailRuim = match[1].toLowerCase().trim();
               for (let r = 2; r < dadosEmail.length; r++) { // Roda a partir da linha 3 (índice 2)
                   if (String(dadosEmail[r][1]).toLowerCase().trim() === emailRuim) {
                       sheetEmail.getRange(r + 1, 2).setValue("Deletado (Bounce)");
                       sheetEmail.getRange(r + 1, 5).setValue("❌ E-mail Inexistente");
                   }
               }
           }
