function formatarSistemaAnjo(sheet) {
  const totalColunasFisicas = sheet.getMaxColumns();
  if (totalColunasFisicas < 12) {
    sheet.insertColumnsAfter(totalColunasFisicas, 12 - totalColunasFisicas);
  }

  const ultimaLinha = sheet.getLastRow();
  const headers = [[
    'DATA/HORA (INÍCIO)', 
    'NOME DO INVESTIGADO', 
    'WHATSAPP', 
    'TIPO DE MISSÃO', 
    'LOCAL/ALVO', 
    'VALOR APORTADO', 
    'STATUS ATUAL', 
    'DESFECHO (LIVRO DA VIDA)', 
    'EMAIL DO ANJO (VINCULO)',
    'AUTORIZADO? (SIM/NÃO)',
    'LINK REDS (BOTÃO)',
    'LINK PROVAS (BOTÃO)'
  ]];

  sheet.getRange("A1:L1").setValues(headers)
       .setBackground("#000000").setFontColor("#d4af37").setFontWeight("bold")
       .setHorizontalAlignment("center").setVerticalAlignment("middle");

  sheet.setFrozenRows(1);

  if (ultimaLinha > 1) {
    const numLinhas = ultimaLinha - 1;
    sheet.getRange(2, 1, numLinhas, 1).setHorizontalAlignment("center");
    sheet.getRange(2, 10, numLinhas, 1).setHorizontalAlignment("center").setFontColor("#e74c3c").setFontWeight("bold");
