  sheet.setColumnWidth(2, 200); 
  sheet.setColumnWidth(9, 180); 
  sheet.setColumnWidth(10, 120); 
  sheet.setColumnWidth(11, 150); 
  sheet.setColumnWidth(12, 150); 
}

