/**
 * FUNÇÃO PRINCIPAL (EXECUTAR ESTA)
 * Você pode colocar um gatilho de tempo para rodar esta função a cada 10 minutos.
 */
function executarRoboVarriduraReds() {
  const pastaRaiz = DriveApp.getFolderById(ID_PASTA_RAIZ_ANJOS);
  const subPastas = pastaRaiz.getFolders();

  // 1. Percorre todas as pastas de clientes
  while (subPastas.hasNext()) {
    let pastaCliente = subPastas.next();
    let arquivos = pastaCliente.getFilesByType(MimeType.PDF);

    // 2. Procura PDFs dentro da pasta do cliente
    while (arquivos.hasNext()) {
      let arquivoPdf = arquivos.next();

      // Pula se for um arquivo que já está na pasta de processados (contingência)
      if (arquivoPdf.getName().includes("PROCESSADO_")) continue;

      console.log("Processando: " + arquivoPdf.getName() + " na pasta " + pastaCliente.getName());

      try {
        // 3. Extrai o texto via OCR
        let textoBruto = extrairTextoOCR(arquivoPdf.getId());

        // 4. Analisa o texto (Inteligência)
        let dadosExtraidos = analisarTextoReds(textoBruto, arquivoPdf.getUrl(), pastaCliente.getName());

        // 5. Salva na Planilha
        salvarNoSistemaAnjo(dadosExtraidos);

        // 6. Organiza o arquivo (Move para subpasta ou renomeia)
        finalizarArquivo(arquivoPdf, pastaCliente);

      } catch (e) {
        console.error("Erro ao processar arquivo: " + e.message);
      }
    }
  }
}

/**
 * Converte PDF para Texto usando Google Drive OCR
 */
function extrairTextoOCR(fileId) {
  let resource = {
    title: 'Temp_OCR_' + fileId,
    mimeType: MimeType.GOOGLE_DOCS
  };

  // Cria arquivo temporário convertido
  let tempFile = Drive.Files.insert(resource, DriveApp.getFileById(fileId).getBlob(), {ocr: true});
  let doc = DocumentApp.openById(tempFile.id);
  let texto = doc.getBody().getText();

  // Apaga o temporário
  Drive.Files.remove(tempFile.id);

  return texto;
}

/**
 * Analisa o texto do REDS e extrai os campos chave
 */
function analisarTextoReds(texto, urlArquivo, nomePasta) {
  let info = {
    data: new Date(),
    nome: nomePasta,
    whatsapp: "Ver na Pasta",
    missao: "Captação REDS",
    detalhes: "REDS Detectado",
    valor: 0,
    status: "Análise Inicial",
    desfecho: urlArquivo,
    crimes: "Não Identificado",
    dataPrisao: "Não Identificada"
  };

  // Regex para capturar Crimes (Padrão: Natureza da Ocorrência)
  let regexCrimes = /PRINCIPAL:\s*(.*)/i;
  let matchCrimes = texto.match(regexCrimes);
  if (matchCrimes) info.crimes = matchCrimes[1].trim();

  // Regex para capturar Data e Hora
  let regexData = /(\d{2}\/\d{2}\/\d{4})\s*às\s*(\d{2}:\d{2})/i;
  let matchData = texto.match(regexData);
  if (matchData) info.dataPrisao = matchData[1] + " " + matchData[2];

  return info;
}

/**
 * Insere os dados na planilha SISTEMA ANJO
 */
function salvarNoSistemaAnjo(dados) {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const sheet = ss.getSheetByName(NOME_PLANILHA) || ss.getActiveSheet();

  // Estrutura: [DATA/HORA, NOME, WHATS, MISSÃO (CRIMES), ALVO, VALOR, STATUS, DESFECHO]
  sheet.appendRow([
    dados.data,
    dados.nome,
    dados.whatsapp,
    "CRIMES: " + dados.crimes,
    "PRISÃO: " + dados.dataPrisao,
    dados.valor,
    dados.status,
    dados.desfecho
  ]);
}

/**
 * Move o arquivo lido para evitar duplicidade
 */
function finalizarArquivo(arquivo, pastaPai) {
  // Cria pasta "LIDOS" se não existir
  let pastaLidos;
  let sub = pastaPai.getFoldersByName("LIDOS");

  if (sub.hasNext()) {
    pastaLidos = sub.next();
  } else {
    pastaLidos = pastaPai.createFolder("LIDOS");
  }

  arquivo.moveTo(pastaLidos);
  arquivo.setName("PROCESSADO_" + arquivo.getName());
}

