            valorAporte: dadosAnjo[i][5] ? String(dadosAnjo[i][5]).replace(/[^\d.,]/g, '') : "0", 
            // Variáveis de sigilo e status extra
            statusDocumentacao: "Aguardando", 
            resumoProcesso: "",
            faseProcessual: "Fase Inicial / Flagrante",
            linkPasta: dadosAnjo[i][10] || "#" // Usando a coluna REDS como link provisório da pasta
          };

          // Passo 2: O Cruza-Dados Mestre
          // O robô procura o nome do alvo lá no "Dashboard Principal"
          if (nomeAlvo && dadosMestre.length > 1) {
             for (let j = 1; j < dadosMestre.length; j++) {
                let nomeNoDashboard = String(dadosMestre[j][1]).toLowerCase(); // Coluna B (Cliente/Pasta)

                // Se achar o cara lá, puxa a inteligência do Super Jurista!
                if (nomeNoDashboard.includes(nomeAlvo.toLowerCase())) {
                    pacoteProcesso.statusDocumentacao = String(dadosMestre[j][3]); // Coluna D
                    pacoteProcesso.linkPasta = String(dadosMestre[j][4]); // Coluna E
                    pacoteProcesso.classeProcessual = String(dadosMestre[j][6]); // Coluna G
                    pacoteProcesso.resumoProcesso = String(dadosMestre[j][12]); // Coluna M
                    pacoteProcesso.faseProcessual = String(dadosMestre[j][17]); // Coluna R
                    break; // Achou, não precisa varrer o resto do Dashboard
                }
             }
          }

          resultado.push(pacoteProcesso);
        }
      }
      return responderJSON(resultado);
    }

    // MURAL PÚBLICO (Não mexemos)
    const muralSheet = ss.getSheetByName(ABA_SISTEMA);
    if(muralSheet){
        const dadosMural = muralSheet.getDataRange().getValues();
        let mural = [];
        for (let i = 1; i < dadosMural.length; i++) {
          if (dadosMural[i][1]) {
            mural.push({ nome: dadosMural[i][1], acao: dadosMural[i][3], status: dadosMural[i][6], desfecho: dadosMural[i][7] });
          }
        }
        return responderJSON(mural);
    }

    return responderJSON([]);

  } catch (f) {
    return responderJSON({ sucesso: false, mensagem: "ERRO: " + f.toString() });
  }
}

// A CHAVE MESTRA: Resposta JSON
function responderJSON(objeto) {
  return ContentService.createTextOutput(JSON.stringify(objeto))
    .setMimeType(ContentService.MimeType.JSON);
}

