// 🔐 SEGURO: Chave lida do PropertiesService (nunca deixe hardcoded no código visível)
const ANTHROPIC_API_KEY = PropertiesService.getScriptProperties().getProperty("ANTHROPIC_API_KEY");

// ✅ Modelo correto e mais atualizado da Anthropic


// =========================================================================
// 🧠 1. MOTOR PRINCIPAL CLAUDE
// =========================================================================
function CHAMAR_CLAUDE(prompt, tipoUso) {
  const url = "https://api.anthropic.com/v1/messages";

  const payload = {
    model: CLAUDE_MODEL,
    max_tokens: 8192,
    messages: [{ role: "user", content: prompt }]
  };

  const options = {
    method: "post",
    headers: {
      "x-api-key": ANTHROPIC_API_KEY,
      "anthropic-version": "2023-06-01",
      "content-type": "application/json"
    },
    payload: JSON.stringify(payload),
    muteHttpExceptions: true
  };

  let tentativas = 0;
  const maxTentativas = 3;

  while (tentativas < maxTentativas) {
    try {
      const response = UrlFetchApp.fetch(url, options);
      const responseCode = response.getResponseCode();
      const json = JSON.parse(response.getContentText());

      if (responseCode === 200 && json.content && json.content.length > 0) {
        return json.content[0].text;
      } else if (responseCode === 429) {
        tentativas++;
        console.log("Claude API (429) - Limite atingido. Tentativa " + tentativas);
        Utilities.sleep(5000); // Pausa de 5s no erro 429
        if (tentativas === maxTentativas) return "❌ Erro Claude: Limite de requisições excedido após 3 tentativas.";
      } else if (responseCode >= 500) {
        tentativas++;
        console.log("Claude API (500+) - Instabilidade. Tentativa " + tentativas);
        Utilities.sleep(5000);
        if (tentativas === maxTentativas) return "❌ Erro Claude: Instabilidade no servidor da Anthropic.";
      } else {
        return "❌ Erro Claude: " + (json.error ? json.error.message : "Resposta inesperada.");
      }
    } catch (e) {
      tentativas++;
      console.log("Falha Crítica Claude: " + e.message);
      Utilities.sleep(3000);
      if (tentativas === maxTentativas) return "❌ Erro Crítico Claude: " + e.toString();
    }
  }
}

// =========================================================================
// 🔀 2. GESTOR DE IA HÍBRIDA (O CÉREBRO DA OPERAÇÃO)
// =========================================================================
function CHAMAR_IA_HIBRIDA(prompt, tipoModelo, motorPreferido) {
  if (motorPreferido === "GEMINI") {
    return CHAMAR_IA_ESCRITORIO(prompt, tipoModelo);
  } 
  else if (motorPreferido === "CLAUDE") {
    return CHAMAR_CLAUDE(prompt, "JURIDICO");
  } 
  else if (motorPreferido === "AUTO") {
    let respostaGemini = CHAMAR_IA_ESCRITORIO(prompt, tipoModelo);

    if (respostaGemini.includes("❌") || respostaGemini.includes("Erro") || respostaGemini.includes("cota")) {
      console.log("⚠️ Motor AUTO: Gemini falhou. Acionando Claude como fallback...");
      Utilities.sleep(3000); 
      let respostaClaude = CHAMAR_CLAUDE(prompt, "JURIDICO");
      return respostaClaude;
    }
    return respostaGemini; 
  }

  return "❌ Erro: Motor preferido inválido.";
}

