// 📝 4. FÁBRICA DE PETIÇÕES (VERSÃO CLAUDE)
// =========================================================================
function gerarPeticaoComClaude() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();

  if (sheet.getName() !== "Dashboard Principal" && sheet.getName() !== "PROCESSOS") {
      Browser.msgBox("❌ ERRO", "Rode esta função no Dashboard Principal.", Browser.Buttons.OK);
      return;
  }

  const linha = sheet.getActiveCell().getRow();
  if (linha < 2) return;

  const nomePlanilha = String(sheet.getRange(linha, 2).getValue()).replace("CLIENTE: ", "").trim();
  const nomePuro = nomePlanilha.split(" - Proc:")[0].trim();

  let inputFatos = Browser.inputBox("📝 Fatos Adicionais", "Digite detalhes específicos para a petição do cliente " + nomePuro + " (Opcional):", Browser.Buttons.OK_CANCEL);
  if (inputFatos === "cancel") return;

  sheet.getRange(linha, 6).setValue("⏳ [CLAUDE] Analisando Teses e Redigindo...");
  SpreadsheetApp.flush();

  try {
    const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO);

    let textoTeses = "";
    const pastasTeses = pastaRaiz.getFoldersByName("00_BANCO_DE_TESES");
    if (pastasTeses.hasNext()) {
      let arqsTeses = pastasTeses.next().getFilesByType(MimeType.GOOGLE_DOCS);
      let cont = 0;
      while (arqsTeses.hasNext() && cont < 3) {
        textoTeses += "\\n" + DocumentApp.openById(arqsTeses.next().getId()).getBody().getText().substring(0, 2000);
        cont++;
      }
    }

    let textoProvas = "";
    const pastasClientes = pastaRaiz.getFoldersByName("01_CLIENTES");
    if (pastasClientes.hasNext()) {
      let clientesDrive = pastasClientes.next().getFoldersByName(nomePuro);
      if (clientesDrive.hasNext()) {
        let pastaCliente = clientesDrive.next();
        let gavetaProvas = pastaCliente.getFoldersByName("02_Provas");
        if (gavetaProvas.hasNext()) {
          let arqsProvas = gavetaProvas.next().getFilesByType(MimeType.GOOGLE_DOCS);
          while (arqsProvas.hasNext()) {
             textoProvas += "\\n" + DocumentApp.openById(arqsProvas.next().getId()).getBody().getText().substring(0, 1000);
          }
        }
      }
    }

    const prompt = `Você é o Advogado Sênior (Dr. Lucas Renan Semim - OAB/MG 222.539).
    Redija uma PETIÇÃO INICIAL completa e impecável.

    FATOS ADICIONAIS: "${inputFatos}"
    CONTEÚDO DE PROVAS: "${textoProvas}"
    BANCO DE TESES: "${textoTeses}"

    ESTRUTURA OBRIGATÓRIA:
    1. Endereçamento e Qualificação (use lacunas [ ] se faltar dado).
    2. Dos Fatos (baseado nas provas e no relato).
    3. Do Direito (baseado nas teses fornecidas).
    4. Dos Pedidos.
    5. Assinatura obrigatória no final: 
       Dr. Lucas Renan Semim
       OAB/MG 222.539
       Sabará-MG`;

    const respostaClaude = CHAMAR_CLAUDE(prompt, "JURIDICO");

    if (respostaClaude.includes("❌")) {
      sheet.getRange(linha, 6).setValue(respostaClaude);
      return;
    }

    let nomeDoc = "[CLAUDE] PETIÇÃO INICIAL - " + nomePuro;
    let novoDoc = DocumentApp.create(nomeDoc);
    novoDoc.getBody().setText(respostaClaude);
    let urlDoc = novoDoc.getUrl();

    // ✅ CORREÇÃO: Busca direta e limpa para evitar o erro do iterator esgotado
    let clientesDriveBusca = pastaRaiz.getFoldersByName("01_CLIENTES").next().getFoldersByName(nomePuro);
    if (clientesDriveBusca.hasNext()) {
        DriveApp.getFileById(novoDoc.getId()).moveTo(clientesDriveBusca.next());
    }

    sheet.getRange(linha, 5).setValue(urlDoc);
    sheet.getRange(linha, 6).setValue("✅ [CLAUDE] Petição Gerada");

    Browser.msgBox("✅ SUCESSO", "Petição inicial redigida pelo Claude com sucesso!", Browser.Buttons.OK);

  } catch (e) {
    sheet.getRange(linha, 6).setValue("❌ Erro Petição Claude: " + e.message);
  }
}

// =========================================================================
// 🔍 5. ANALISADOR DE PROCESSOS (VERSÃO CLAUDE)
// =========================================================================
function analisarProcessoComClaude() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();

  if (sheet.getName() !== "Dashboard Principal" && sheet.getName() !== "PROCESSOS") {
      Browser.msgBox("❌ ERRO", "Rode esta função no Dashboard Principal.", Browser.Buttons.OK);
      return;
  }

  const linha = sheet.getActiveCell().getRow();
  if (linha < 2) return;

  const nomePlanilha = String(sheet.getRange(linha, 2).getValue()).replace("CLIENTE: ", "").trim();
  const nomePuro = nomePlanilha.split(" - Proc:")[0].trim();

  sheet.getRange(linha, 6).setValue("⏳ [CLAUDE] Lendo autos..."); 
  SpreadsheetApp.flush();

  try {
    const pastaRaiz = DriveApp.getFolderById(ID_RAIZ_ESCRITORIO);
    const pasta01 = pastaRaiz.getFoldersByName("01_CLIENTES").next();

    let clientesDrive = pasta01.getFoldersByName(nomePlanilha);
    if (!clientesDrive.hasNext()) clientesDrive = pasta01.getFoldersByName(nomePuro);

    if (!clientesDrive.hasNext()) {
        sheet.getRange(linha, 6).setValue("❌ Pasta não encontrada");
        return;
    }

    let clientePasta = clientesDrive.next();
    let textoProcessoCompleto = "";

    function lerArquivos(pasta) {
       let arquivos = pasta.getFilesByType(MimeType.GOOGLE_DOCS);
       while(arquivos.hasNext()) {
         let arq = arquivos.next();
         textoProcessoCompleto += "\\n[DOC: " + arq.getName() + "]\\n" + DocumentApp.openById(arq.getId()).getBody().getText().substring(0, 3000);
       }
    }

    lerArquivos(clientePasta);
    let subpastas = clientePasta.getFolders();
    while(subpastas.hasNext()) lerArquivos(subpastas.next());

    if (textoProcessoCompleto.trim() === "") {
        sheet.getRange(linha, 6).setValue("⚠️ Sem documentos na pasta");
        return;
    }

    sheet.getRange(linha, 6).setValue("🧠 [CLAUDE] Raciocinando...");
    SpreadsheetApp.flush();

    const prompt = `ATUE COMO UM JURISTA SÊNIOR (DR. LUCAS RENAN SEMIM).
    Faça uma análise processual transversal destes documentos:
    "${textoProcessoCompleto.substring(0, 15000)}"

    Responda ESTRITAMENTE usando as TAGS abaixo (sem markdown adicional fora delas):
    [CLASSE_PROCESSUAL]...[/CLASSE_PROCESSUAL]
    [PARTE_CONTRARIA]...[/PARTE_CONTRARIA]
    [FASE_DO_PROCESSO]...[/FASE_DO_PROCESSO]
    [RESUMO_FATOS_E_ANDAMENTO]...[/RESUMO_FATOS_E_ANDAMENTO]
    [PROXIMA_ACAO_ESTRATEGICA]...[/PROXIMA_ACAO_ESTRATEGICA]
    [MINUTA_PETICAO]...[/MINUTA_PETICAO]`;

    let respostaClaude = CHAMAR_CLAUDE(prompt, "ANALISE");

    if (respostaClaude.includes("❌")) {
       sheet.getRange(linha, 6).setValue(respostaClaude);
       return;
    }

    function extrairTag(texto, tag) {
       let regex = new RegExp("\\[" + tag + "\\]([\\s\\S]*?)(?:\\[\\/" + tag + "\\])", "i");
       let m = texto.match(regex);
       return m && m[1] ? m[1].replace(/^\\*\\*|\\*\\*$/g, "").trim() : "Não extraído.";
    }

    let classe = extrairTag(respostaClaude, "CLASSE_PROCESSUAL");
    let parte = extrairTag(respostaClaude, "PARTE_CONTRARIA");
    let fase = extrairTag(respostaClaude, "FASE_DO_PROCESSO");
    let resumo = extrairTag(respostaClaude, "RESUMO_FATOS_E_ANDAMENTO");
    let acao = extrairTag(respostaClaude, "PROXIMA_ACAO_ESTRATEGICA");
    let minuta = extrairTag(respostaClaude, "MINUTA_PETICAO");

    if (resumo === "Não extraído.") {
       sheet.getRange(linha, 6).setValue("❌ Resposta fora do padrão.");
       return;
    }

    if (classe !== "Não extraído.") sheet.getRange(linha, 7).setValue(classe);
    if (parte !== "Não extraído.") sheet.getRange(linha, 12).setValue(parte);
    if (fase !== "Não extraído.") sheet.getRange(linha, 18).setValue(fase);
    sheet.getRange(linha, 13).setValue(resumo);
    sheet.getRange(linha, 14).setValue(acao);

    // ✅ CORREÇÃO: Atualiza o Dossiê na ordem visual correta
    let arquivosDossie = clientePasta.searchFiles("title contains 'DOSSIÊ VIVO'");
    if (arquivosDossie.hasNext()) {
        let dossie = arquivosDossie.next();
        let body = DocumentApp.openById(dossie.getId()).getBody();
        const dataHoje = Utilities.formatDate(new Date(), "GMT-3", "dd/MM/yyyy 'às' HH:mm");

        let insertIndex = body.getNumChildren(); 
        for (let j = 0; j < body.getNumChildren(); j++) {
           if (body.getChild(j).getText().includes("==================================================")) {
              insertIndex = j + 1; break;
           }
        }

        body.insertParagraph(insertIndex, "📅 ATUALIZAÇÃO [CLAUDE]: " + dataHoje).setBold(true).setFontSize(13);
        body.insertParagraph(insertIndex + 1, "📌 Fase Processual: " + fase).setBold(false).setFontSize(11);
        body.insertParagraph(insertIndex + 2, "📖 Situação Atual: " + resumo).setBold(false).setFontSize(11);
        body.insertParagraph(insertIndex + 3, "🎯 Estratégia: " + acao).setBold(false).setFontSize(11);
        body.insertParagraph(insertIndex + 4, "--------------------------------------------------").setBold(true);

        if (minuta !== "Não extraído." && minuta.length > 20) {
            body.insertParagraph(insertIndex + 5, "📄 MINUTA GERADA:");
            body.insertParagraph(insertIndex + 6, minuta);
            body.insertParagraph(insertIndex + 7, "==================================================");
        }
    }

    sheet.getRange(linha, 6).setValue("✅ [CLAUDE] Dossiê Atualizado");
    Browser.msgBox("✅ SUCESSO", "Análise concluída pelo Claude e Dossiê atualizado!", Browser.Buttons.OK);

  } catch (e) {
    sheet.getRange(linha, 6).setValue("❌ Erro Análise Claude: " + e.message);
  }
}

